programs.sol:
"""An I / Roman-numeral spelling feature, strongest for II and III.

Predict strengths for listed Roman numerals, adjusting for case,
word boundaries, and preceding clause words or numbering labels. Capital
I also covers the English pronoun: document starts are especially strong;
joining an uppercase word is weak. Punctuation-attached forms are weaker.

Smaller responses cover Unicode numeral forms, selected Chinese/German/
Russian first-person spellings, the I-like spelling Il, the name suffix Jr,
and several number words. A byte-prefix token shared by Unicode Roman
numerals and fractions responds even before its character is complete.
Everything else is zero: diffuse weak lexical responses are omitted.
"""

READS = ()

# Qwen token for UTF-8 E2 85, shared by Roman-numeral/fraction glyphs.
NUMBER_FORMS_PREFIX = 70467

ROMAN_UPPER = {
    'I': 1.4,
    'II': 6.0,
    'III': 6.4,
    'IV': 3.5,
    'V': 0.15,
    'VI': 2.0,
    'VII': 4.6,
    'VIII': 5.65,
    'IX': 2.3,
    'X': 0.3,
    'XI': 1.85,
    'XII': 4.7,
    'XIII': 3.6,
    'XIV': 2.8,
    'XV': 1.4,
    'XVI': 2.8,
    'XX': 1.0,
    'XXX': 0.7,
    'XL': 0.35,
}
ROMAN_LOWER = {'i': 0.1, 'ii': 2.65, 'iii': 3.9, 'iv': 1.35,
               'vi': 0.34, 'ix': 0.45, 'x': 0.07, 'xx': 0.65,
               'xxx': 0.6, 'xiv': 0.85}
CLAUSE_WORDS = {
    'what', 'where', 'how', 'why', 'when', 'if', 'whether',
    'do', 'did', 'can', 'could', 'should', 'would', 'will',
    'as', 'that', 'because', 'while', 'since', 'think', 'thought',
}


def step(carry, prefix, upstream):
    if prefix.token_ids[-1] == NUMBER_FORMS_PREFIX:
        return None, 3.65
    raw = prefix.token_strings[-1]
    char = raw[-1:]
    if '\ufffd' in raw:
        char = prefix.text_prefixes[-1][-1:]
    if char in {'Ⅰ', 'Ⅱ', 'Ⅲ', 'Ⅳ', 'Ⅴ', 'Ⅵ', 'Ⅹ'}:
        return None, {'Ⅰ': 4.0, 'Ⅱ': 6.1, 'Ⅲ': 6.6, 'Ⅳ': 4.3,
                      'Ⅴ': 1.9, 'Ⅵ': 3.4, 'Ⅹ': 0.9}[char]
    if char and char in '②③④⑤⑥⑦⑧':
        return None, 0.9 if char in '②③' else 0.65
    token = raw.strip()
    stem = token.lstrip('([{<.:,;-/_\"\'“”…—')
    affixed = stem != token
    token = stem
    start = (len(prefix.token_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if start else prefix.token_strings[-2]
    word = previous.strip().lower()
    embedded = bool(not affixed and raw and not raw[0].isspace() and previous
                    and previous[-1].isalnum())
    value = 0.0
    if token in ROMAN_UPPER:
        value = ROMAN_UPPER[token]
        if token == 'I':
            if start:
                value = 1.83 if raw[0].isspace() else 2.23
            elif embedded:
                value = 0.2 if previous.strip().isupper() else 1.18
            elif raw[0].isspace():
                value = 0.97 if word in CLAUSE_WORDS else 1.23
                if previous and not previous[-1].isalnum():
                    value = 1.35
        elif embedded and 'I' in token and len(token) > 1:
            value -= {'II': 2.1, 'VI': 0.8}.get(token, 1.7)
        elif len(token) == 1 and not raw[0].isspace():
            value -= 0.05
        if token in {'II', 'III'}:
            if word == 'war':
                value -= 1.5
            elif word in {'table', 'type', 'phase', 'volume'}:
                value -= 1.0
    elif token in ROMAN_LOWER:
        value = ROMAN_LOWER[token]
        if embedded:
            value -= {'i': 0.12, 'ii': 0.75, 'iii': 0.85, 'iv': 0.85,
                      'vi': 0.12, 'ix': 0.38}.get(token, 0.0)
        elif token == 'ii' and raw[0].isspace():
            value += 0.4
    if affixed:
        value *= 0.78
    if token == 'Il':
        value = 0.85
    elif token == 'Jr':
        value = 1.35
    elif token in {'我', 'ich', 'Ich', 'я', 'Я'}:
        if token != '我' and embedded:
            return None, 0.0
        value = {'我': 0.75, 'ich': 0.42, 'Ich': 0.55,
                 'я': 0.23, 'Я': 0.32}[token]
    elif token in {'eleven', 'twelve', '二', '三'}:
        value = {'eleven': 0.54, 'twelve': 0.66,
                 '二': 0.6, '三': 0.32}[token]
    return None, float(value)

programs.haiku:
"""Roman-numeral "I" detector.

The component reads the letter I when it stands alone as a token. It is silent on
almost everything, but responds to:
  * the English pronoun "I" (about 1.3, a little more at the start of a sentence);
  * Roman numerals containing I, scaled by how many I's they have: a single I
    (IV, VI, IX, XIV: about 2), two I's (II, XII: about 5), three I's (III, VIII: about 6).
    Lower-case ii / iii respond at about half strength; lower-case single i does not.
The response is largest on name and title suffixes such as "World War II" or "Part III".
"""

READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    if s == "I":
        return None, 1.3
    if not s or not set(s.upper()) <= set("IVX"):
        return None, 0.0
    n = s.upper().count("I")
    if n == 0:
        return None, 0.0
    if n == 1:
        return None, (2.0 if s.isupper() else 0.0)
    value = 5.0 if n == 2 else 6.0
    return None, (value * 0.5 if s.islower() else value)

programs.luna:
"""Mark the standalone first-person word, chiefly English capital I."""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word == "I":
        return None, 1.35
    if word in ("Ich", "我"):
        return None, 0.60
    return None, 0.0

programs.sol:
"""Negative lexical pulses for grammar and speech terminology.

Parts-of-speech names are strongest; sentence units, speakers and
inflectional terminology are weaker. Small pulses cover ambiguous
structural words and grammar-name fragments. The current word buffer
recognizes a few grammar terms split across tokens, not sentence syntax.
Chinese sentence/word and grammatical-role morphemes are also included.
Most tokens receive zero.
"""
import re

READS = ()

PARTS_OF_SPEECH = {'noun', 'verb', 'adjective', 'adverb'}
PLURAL_NAMES = {'nouns', 'verbs', 'adjectives', 'adverbs', 'ouns', 'jectives'}
SENTENCE_UNITS = {'sentence', 'sentences', 'phrase', 'phrases', 'comma', 'commas'}
GRAMMAR_TERMS = {
    'predicate', 'predicates', 'plural', 'singular', 'passive', 'verbal',
    'conjunction', 'preposition', 'grammar', 'gramm', 'atical', 'subj',
    'feminine', 'masculine', 'indicative', 'punctuation', 'modifier',
    'modifiers', 'suffix', 'adj', 'conj', 'pron', 'oun',
}
STRUCTURAL_WORDS = {
    'syntax', 'construction', 'structure', 'subject', 'statement', 'statements',
    'present', 'past', 'future', 'perfect', 'particle', 'agreement', 'auxiliary',
    'relative', 'article', 'voice', 'aspect', 'manner', 'expression', 'attribute',
    'line', 'lines', 'logical',
}
ENDINGS = {'ative', 'ativ', 'ativa', 'itive', 'ive', 'ives', 'ial', 'ical'}
COMPLETED_TERMS = {
    'pronoun': -2.8, 'pronouns': -3.5, 'adverb': -2.9,
    'subjunctive': -2.1, 'quantifier': -1.6, 'quantifiers': -1.9,
    'participle': -2.5, 'grammatical': -1.4, 'accusative': -2.0,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_word, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if word in PLURAL_NAMES:
        value = -2.45
    elif word in PARTS_OF_SPEECH:
        value = -1.85
    elif word in {'clause', 'clauses', 'tense'}:
        value = -1.3
    elif word == 'conditional':
        value = -0.95
    elif word in SENTENCE_UNITS:
        value = -0.8
    elif word == 'speaker':
        value = -0.76 if token == ' speaker' else -0.34
    elif word == 'speakers':
        value = -0.43
    elif word in GRAMMAR_TERMS:
        value = -0.6
    elif word in STRUCTURAL_WORDS or word in ENDINGS:
        value = -0.18
    elif word in {'ifier', 'ifiers'}:
        value = -0.35
    elif word in {'句', '句子'}:  # sentence
        value = -1.25
    elif word in {'词', '詞', '语', '語', '状', '狀', '宾', '賓'}:
        value = -0.6
    elif word in {'动作', '動作', '手法'}:  # action / method
        value = -0.6
    elif word in {'名词', '名詞', '语法', '語法'}:  # noun / grammar
        value = -1.4

    match = re.search(r'[a-z]+$', old_word + token.lower())
    full_word = match.group()[-40:] if match else ''
    if word in {'oun', 'ouns', 'verb', 'ive', 'ative', 'ifier', 'ifiers',
                'iple', 'atical'}:
        value = COMPLETED_TERMS.get(full_word, value)
    text = (tail + token)[-8:]
    if word in {'语', '語'} and text[-2:-1] in set('主宾賓谓謂定状狀补補'):
        value = -3.0  # Chinese subject, object, predicate, etc.
    if word in {'词', '詞'} and text.endswith(('动词', '動詞', '形容词', '形容詞')):
        value = -2.2
    if word in {'statement', 'statements'} and old_word == 'conditional':
        value = -2.3 if word == 'statement' else -1.6
    return (doc, full_word, text), float(value)

programs.luna:
"""A weak negative prediction for a few speech and grammar words.

The harvest repeatedly shows strong negative responses to speaker and to terms
such as sentence, clause, comma, and verb. A small value limits false alarms;
this ignores context and other, less systematic activations.
"""

import unicodedata

READS = ()

SPEECH_AND_GRAMMAR = frozenset({
    "speaker", "speakers", "speech", "verbal", "nonverbal", "message",
    "dialogue", "conversation", "pronounced", "sentence", "sentences",
    "word", "words", "phrase", "phrases", "clause", "clauses", "statement",
    "statements", "comma", "commas", "punctuation", "adjective", "adjectives",
    "noun", "nouns", "verb", "verbs", "pronoun", "pronouns", "auxiliary",
})


def _word_char(char):
    return char.isalnum() or unicodedata.category(char).startswith("M")


def _current_word(tokens):
    pieces = []
    for token in reversed(tokens):
        if not any(char.isalnum() for char in token):
            return ""
        end = len(token)
        while end and not _word_char(token[end - 1]):
            end -= 1
        start = end
        while start and _word_char(token[start - 1]):
            start -= 1
        if start < end:
            pieces.append(token[start:end])
        if start or any(char.isspace() for char in token):
            break
    return "".join(reversed(pieces)).casefold()


def step(carry, prefix, upstream):
    word = _current_word(prefix.token_strings)
    return None, -0.27 if word in SPEECH_AND_GRAMMAR else 0.0

programs.sol:
"""Approximate the negative response to word-internal m fragments.

Short m-initial pieces are strongest when joined to a preceding letter.
Repeated m, word boundaries, complete code words, and common word endings
weaken the response. Similar m letters/syllables in other scripts share
this signal. It does not memorize arbitrary vocabulary items.
"""
import unicodedata

READS = ()
M_LETTERS = 'mмμمמमমਮમମமమಮമมມ'
KANA_M = 'まみむめもマミムメモ'
CODE_WORDS = {
    'max', 'map', 'mod', 'math', 'main', 'model', 'module', 'method',
    'merge', 'message', 'memory', 'malloc', 'matrix', 'metadata',
}
WORD_ENDINGS = {
    'ment', 'ments', 'mente', 'mento', 'mental', 'meter', 'meters',
    'metry', 'mission', 'missions', 'ming',
}
KANA_FUNCTION_FORMS = {
    'も', 'ます', 'ました', 'ません', 'まで', 'また', 'もの', 'ませ',
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if not s:
        return None, 0.0
    c, low, n = s[0], s.lower(), len(s)
    roman = c in 'mM'
    # Hangul packs 21 vowels and 28 final-consonant choices per initial.
    # Initial number 6 is ㅁ (m); final number 0 means no final consonant.
    syllable = c in KANA_M or (
        '\uac00' <= c <= '\ud7a3' and (ord(c) - 0xac00) // 588 == 6)
    if roman:
        size = {1: 1.05, 2: 1.4, 3: 1.2, 4: 0.8}.get(n, 0.4)
        if c == 'M':
            size = 0.6 if n == 1 else size if s.isupper() else 0.25
        if low in CODE_WORDS:
            size = 0.5 if n <= 3 else 0.2
        if low in WORD_ENDINGS:
            size = 0.24
        if n == 2 and low[1] in 'cdgkrl':
            size += 0.35
        if n == 3 and low[2] in 'mn':
            size -= 0.3
    elif c.casefold() in M_LETTERS:
        size = 1.0 if n <= 3 else 0.6
    elif c in KANA_M:
        size = 0.6 if n == 1 else 0.2
        if n == 2 and s[1] in 'ャュョゃゅょンんー':
            size = 0.8
        if s in KANA_FUNCTION_FORMS:
            size = 0.04
    elif syllable:
        size = 0.6 if (ord(c) - 0xac00) % 28 == 0 else 0.13
    elif low.startswith(('im', 'am', 'em', 'om', 'um')):
        size = 0.5 if low == 'im' else 0.2
        if low.endswith(('ment', 'mente', 'mento')):
            size = 0.0
    else:
        return None, -0.0007
    p = ''
    # Only a character from this document may join to the current fragment.
    if (len(prefix.token_strings) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        p = prefix.token_strings[-2][-1:]
    letter = p.isalpha() or (p and unicodedata.category(p).startswith('M'))
    if letter:
        strength = 1.0
    elif p == '�':
        strength = 0.75
    elif p.isdigit():
        strength = 0.22
    else:
        strength = 0.03
    repeated = p and p.casefold() in M_LETTERS
    if repeated:
        strength = 0.3 if n >= 3 else 0.2
    if syllable:
        strength = 1.0
    if (roman and letter and not repeated
            and low not in CODE_WORDS | WORD_ENDINGS):
        size += 0.3 * p.isupper() + 0.3 * (p.lower() in 'bcdgkptqhlr')
    return None, float(-0.0007 - size * strength)

programs.luna:
"""Give a small negative response when a token begins with an M-like letter.

The clearest harvested responses are on tokens beginning with Latin M, or its
counterparts such as Greek mu, Cyrillic em, Arabic meem, and Japanese kana.
"""
import unicodedata

READS = ()


def is_m(char):
    name = unicodedata.name(char, "")
    return char.casefold() == "m" or any(
        mark in name
        for mark in ("LETTER EM", "LETTER MU", "LETTER MI", "LETTER M", "MEEM", "MO MA")
    )


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lstrip()
    if token and is_m(token[0]):
        return None, -0.12
    return None, 0.0

programs.sol:
"""A mixed lexical feature: negative for association, companionship, assistant,
and persistence/consistency vocabulary; positive for money notation, copyright
signs, and a small list of places and Chinese city characters.

Weights distinguish inflections, case and leading spaces. Association stems
also activate their suffix pieces and some immediately following prepositions.
Recent LaTeX notation lowers dollar-sign predictions. All unrecognized tokens
return zero. Only the last 256 text characters and the previous word are kept;
state resets at document boundaries. This approximates the main lexical spikes,
not the many small responses to other words or undecodable byte fragments.
"""
import re

READS = ()

ASSOCIATION = {
    'associ': -3.2, 'assoc': -2.8, 'associate': -4.9,
    'associates': -4.3, 'associated': -3.6, 'associating': -4.7,
    'association': -2.85, 'associations': -2.8, 'associative': -1.5,
}
COMPANIONSHIP = {
    'accompany': -1.95, 'accompanied': -1.83, 'accompanying': -2.12,
    'accompanies': -2.3, 'companion': -2.55, 'companions': -2.2,
    'compan': -1.4, 'panion': -2.1,
    'alongside': -0.63, 'escort': -0.6, 'attendant': -1.5,
    'affiliated': -0.85, 'accessory': -1.1, 'accessories': -0.9,
    'attached': -0.7, 'attaching': -0.56,
}
CHINESE_COMPANIONSHIP = {
    '伴': -6.6, '伴随': -4.3, '伴随着': -3.1, '伴有': -3.1,
    '伙伴': -1.5, '同伴': -1.2, '伴侣': -1.6, '相伴': -2.7,
    '陪': -2.2, '陪伴': -2.35, '陪同': -2.1, '陪着': -1.6,
    '协会': -1.27, '附': -0.9, '附加': -0.72,
    '附件': -0.83, '附属': -1.12,
}
PERSISTENCE = {
    'consistent': -0.97, 'consistently': -0.71, 'consistency': -0.63,
    'inconsistent': -0.67, 'persistent': -1.5, 'persistence': -0.93,
    'persist': -0.65, 'persisted': -0.83, 'persists': -0.8,
}
PLACES = {
    'London': 0.95, 'England': 0.6, 'Berlin': 0.73,
    'UK': 0.41, 'British': 0.33, '城': 2.07, '京': 1.4,
}
CURRENCY = {
    '£': 4.85, '€': 2.4, '₹': 1.4, '￥': 1.6, '¥': 2.1,
    '¢': 1.3, 'EUR': 1.2, 'Rs': 0.9, '人民币': 1.4, '円': 0.44,
}
ASSOCIATION_SUFFIXES = {
    'ating': -4.7, 'ations': -2.3, 'ation': -1.9,
    'ated': -3.05, 'ates': -3.2, 'ative': -0.8,
}
MATH_NOTATION = re.compile(
    r'\\(?:frac|math[A-Za-z]*|begin|end|sum|int|sqrt|left|right|alpha|'
    r'beta|gamma|theta|text|times|cdot)\b|'
    r'\$[A-Za-z](?:[_^][^$]*)?\$|\$\$|\$\\'
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous_word = '', ''
    else:
        _, recent, previous_word = carry
    text = recent + token
    spelling = token.strip(' _-.')
    word = spelling.lower()
    stripped = token.strip()
    value = 0.0

    if (word in ASSOCIATION_SUFFIXES
            and re.search(r'associ\Z', recent, re.IGNORECASE)):
        value = ASSOCIATION_SUFFIXES[word]
    elif word in ASSOCIATION:
        value = ASSOCIATION[word]
        if spelling[0].isupper() and word in ('association', 'associations'):
            value += 0.9
        elif not token.startswith(' ') and word in ('association', 'associated'):
            value += 0.55
    elif word in COMPANIONSHIP:
        value = COMPANIONSHIP[word]
        if spelling[0].isupper() and word == 'companion':
            value += 0.55
    elif word in PERSISTENCE:
        value = PERSISTENCE[word]
    elif word in ('assistant', 'assistants'):
        if spelling[0].isupper():
            value = -2.55
        elif stripped == 'assistant' and not token.startswith(' '):
            value = -1.37
        else:
            value = -1.94 if word == 'assistant' else -1.45
    elif stripped in CHINESE_COMPANIONSHIP:
        value = CHINESE_COMPANIONSHIP[stripped]
    elif stripped in PLACES:
        value = PLACES[stripped]
    elif word == 'of' and previous_word in ('association', 'companion'):
        value = -1.4
    elif word == 'with' and previous_word in ('associated', 'associating'):
        value = -0.44
    elif word == 'by' and previous_word == 'accompanied':
        value = -0.8
    elif word == 'to' and previous_word == 'associated':
        value = -0.28

    sign = stripped.removeprefix('(')
    if sign in CURRENCY:
        value = CURRENCY[sign]
        if not token.startswith(' ') and sign in ('£', '€'):
            value -= 0.9 if sign == '£' else 0.3
    if '$' in token:
        # Braces, doubled dollars and backslash commands mark mathematics or
        # interpolation, not money. Escaped dollars denote literal money.
        if stripped.endswith('\\$'):
            value = 1.6 if token.startswith(' ') else 1.05
        elif '$$' in token or '${' in token or '$\\' in token:
            value = -0.12
        elif stripped == '$':
            math = bool(MATH_NOTATION.search(recent))
            if token.endswith('$'):
                value = (-0.08 if math else 0.65) if token.startswith(' ') else (
                    -0.05 if math else 0.52
                )
        elif stripped.endswith('$') and stripped[:-1] in ('(', '/', '"', "'", '`'):
            value = 0.7

    if stripped == '©':
        value = 1.4 if 'copyright' in recent[-40:].lower() else 0.65
    return (doc, text[-256:], word), float(value)

programs.luna:
"""Recognize a few rare lexical bursts in this down-projection component.

It is usually quiet, but tends to be negative at assistant-turn headers and
association-word pieces, and positive at currency markers.
"""

import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()

    if token == "assistant" and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2] == "<|im_start|>":
            return None, -1.4

    if "associ" in word.lower():
        return None, -3.0

    if "€" in word:
        return None, 2.8
    if any(unicodedata.category(char) == "Sc" for char in word):
        return None, 0.8

    return None, 0.0

programs.sol:
"""Source/destination markers, especially when things enter or leave a group.

Positive examples are 'add ... to', 'remove ... from', 'insert ... into' and
'include ... in'. Recent operation words give fading evidence across intervening
objects. Local grammatical cues adjust that evidence: ordinary infinitive 'to'
is weaker, while 'native to' and 'important to' are stronger. Articles and 'of'
following operation words can have negative responses. This is a lexical
approximation, not a semantic parser; unrecognized words get zero.
"""
import re
READS = ()

# Lemmas and nominal forms; ordinary inflections are recognized below.
FAMILIES = {
    'add': 'add',
    'addition': 'addition additional',
    'contribute': 'contribute contribution append',
    'insert': 'insert insertion incorporate incorporation integrate integration',
    'introduce': 'introduce introduction',
    'inject': 'inject injection substitute substitution plug',
    'include': 'include inclusion embed',
    'remove': (
        'remove removal delete deletion eliminate elimination exclude '
        'exclusion miss absent absence omit omission ban'
    ),
    'extract': (
        'subtract subtraction extract extraction separate separation '
        'isolate isolation detach'
    ),
    'transfer': (
        'bring brought give given gave send sent deliver distribute '
        'distribution attach attachment assign assignment admit submit '
        'present transfer return back put place'
    ),
    'location': 'native endemic indigenous exclusive unique',
    'association': (
        'belong membership respect regard attention exposure expose '
        'available access accessible'
    ),
    'importance': 'important necessary crucial essential vital indispensable rare',
    'infinitive': (
        'want wish hope need try attempt decide tend fail plan aim manage '
        'seem allow enable help learn able unable likely ready easy easier '
        'hard difficult possible ability capacity opportunity way time '
        'potential'
    ),
    'come': 'come came',
    'motion': 'move travel go went walk run ran',
    'look': 'look investigate investigation turn convert conversion transform',
}
CLASSES = {word: name for name, words in FAMILIES.items() for word in words.split()}


def classify(word):
    if word in CLASSES:
        return CLASSES[word]
    roots = []
    if word.endswith(('ies', 'ied')):
        roots.append(word[:-3] + 'y')
    for ending in ('s', 'es', 'ed', 'ing'):
        if word.endswith(ending):
            root = word[:-len(ending)]
            roots.extend((root, root + 'e'))
            if len(root) > 1 and root[-1] == root[-2]:
                roots.append(root[:-1])
    return next((CLASSES[root] for root in roots if root in CLASSES), None)


# The endpoint favored by each change-of-membership operation.
ENDPOINT = {
    'add': {'to': 4.1, 'into': 1.3},
    'addition': {'to': 2.6},
    'contribute': {'to': 2.1},
    'insert': {'into': 3.4},
    'introduce': {'to': 1.5, 'into': 2.2},
    'inject': {'into': 1.45},
    'include': {'into': 1.1, 'in': 1.5},
    'remove': {'from': 2.6},
    'extract': {'from': 0.8},
    'transfer': {'to': 0.85, 'into': 1.2},
}
TO_CUE = {'location': 1.65, 'association': 0.8, 'importance': 1.4,
          'infinitive': -0.2, 'come': 0.55}
ARTICLE = {'add': -0.9, 'insert': -0.5, 'introduce': -0.8,
           'include': -0.3, 'remove': -0.45, 'extract': -0.3, 'come': -0.5}
BASE = {'to': (0.12, 0.0), 'from': (0.96, 1.13),
        'into': (0.56, 0.22), 'in': (0.0, -0.05), 'of': (0.0, -0.07),
        'onto': (0.3, 0.11)}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, ages = ('', {}) if carry is None or carry[0] != doc else carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip().strip('._-("\'').lower()
    match = re.search(r'([A-Za-z]+)[ \t]*$', tail)
    previous = match.group(1).lower() if match else ''
    family = classify(previous)
    ages = {name: age + 1 for name, age in ages.items() if age < 20}
    if family in ENDPOINT:
        ages[family] = 0

    value = BASE.get(word, (0.0, 0.0))[0 if raw[:1].isspace() else 1]
    if word == 'to':
        value += TO_CUE.get(family, 0.0)
    elif word == 'from' and family == 'come':
        value -= 0.6
    elif word == 'into':
        value += {'motion': -0.35, 'look': -0.85, 'come': 0.4}.get(family, 0)
    elif word == 'in' and family == 'come':
        value -= 0.5
    elif word in ('the', 'a', 'an'):
        value = ARTICLE.get(family, 0.0) * (1.0 if word == 'the' else 0.75)
    elif word == 'of':
        value += {'addition': -1.3, 'include': -0.9, 'contribute': -0.7,
                  'introduce': -0.7, 'insert': -0.5, 'remove': -0.6,
                  'extract': -0.3, 'come': -0.6}.get(family, 0.0)

    decay = {'to': 0.75, 'from': 0.85, 'into': 0.85, 'in': 0.55}.get(word, 0.0)
    for name, age in ages.items():
        if word == 'into' and age != min(ages.values()):
            continue
        strength = decay ** age
        if word == 'to' and family == 'infinitive':
            strength *= 0.1
        value += ENDPOINT[name].get(word, 0.0) * strength
    if word == 'into' and raw.isupper() and previous == 'insert':
        value = 5.1  # SQL INSERT INTO.

    current = classify(word)
    nominal = word.endswith(('tion', 'tions', 'al', 'als'))
    if current in ('insert', 'introduce', 'remove'):
        value = (0.15 if nominal else -0.25)
    elif current == 'add':
        if raw.startswith('.'):
            value = 0.2
        else:
            value = -0.4 if word == 'adding' else -0.08
    elif current == 'addition':
        value = 0.16
    elif word.startswith('subtract'):
        value = -0.6
    elif current == 'come':
        value = -0.18
    return (doc, (tail + raw)[-80:], ages), float(value)

programs.luna:
"""Approximate a sparse activation pattern with a few common prepositions.

The newest token gets a small positive score when it is exactly from, to,
or into (ignoring surrounding whitespace and case); all other tokens get zero.
"""
READS = ()

PREPOSITION_SCORES = {
    "from": 0.50,
    "to": 0.42,
    "into": 0.57,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return None, float(PREPOSITION_SCORES.get(word, 0.0))

programs.sol:
"""Local reference phrases, especially 'this case', 'this time', and 'this is'.

A demonstrative usually gives a negative pulse on its following word. Named
groups of situation, time, type, and other reference nouns have stronger pulses
than unclassified words. Plurals after this/that weaken the pulse. The response also covers a short
'kind of' phrase, multilingual demonstratives, and `this->` member access.
Numeral modifiers and named months can give positive pulses. Most other tokens
are predicted as zero. Only two preceding tokens are remembered, and they are
forgotten at each document boundary.
"""
READS = ()

# Empirical strength bands for familiar demonstrative/reference phrases.
SITUATING = set('case time point reason purpose'.split())
FRAMING = set('way kind type context stage instance manner respect regard'.split())
ABSTRACT_REFERENTS = set('problem question situation scenario phenomenon world fact sense '
             'aspect goal hypothesis category life planet'.split())
TOPICS_AND_RELATIONS = set('topic issue matter task exercise feature effect part country '
             'side direction level style occasion amount'.split())
PROCESSES_AND_QUALIFIERS = set('method approach process technique strategy invention theory '
                'area option step result decision condition event action activity '
                'moment period day particular same latter'.split())
CONTENT = set('example one value message research law data technology'.split())
TOOLS = set('section function work tool system model'.split())
PUBLICATIONS = set('study paper article review post page report blog'.split())
NUMBERS = set('two three four five six seven eight nine ten'.split())

# Inflected equivalents of 'this' in several languages.
THIS_WORDS = set('ce cet cette este esta esto esse essa isto questo questa '
                 'dieser diese dieses diesem diesen '
                 'этот эта этом этого этой данном данный данной '
                 'acest această هذا هذه'.split())
ASIAN_THIS = {'这', '這', '此', '这个', '這個', '这种', '這種', '这一', '這一',
              '这样', '這樣', '该', '在此', '在这', '在這', '在这个', '在这种'}


def strength(text):
    """The referential strength of the next word, before plural attenuation."""
    w = text.strip().lower()
    root = w[:-1] if w.endswith('s') and not w.endswith('ss') else w
    for words, amount in ((SITUATING, 3.9), (FRAMING, 3.2), (ABSTRACT_REFERENTS, 2.9),
                          (TOPICS_AND_RELATIONS, 2.3), (PROCESSES_AND_QUALIFIERS, 1.8),
                          (CONTENT, 1.4), (TOOLS, 1.0)):
        if w in words or root in words:
            return amount, w not in words
    if w == 'information':
        return 2.65, False
    if w in NUMBERS:
        return -1.6, False
    if text.strip() in {'January', 'February', 'March', 'April', 'May', 'June',
                        'July', 'August', 'September', 'October',
                        'November', 'December'}:
        return -1.1, False
    if w.endswith('ly'):
        return -0.2, False
    if w == 'is':
        return 1.25, False
    if w in {'was', 'are', 'were', 'can', 'means', 'happens', 'happened'}:
        return 0.85, False
    if w in {'has', 'have', 'had', 'will', 'would', 'does', 'do', 'did'}:
        return 0.5, False
    if w in {'could', 'may', 'might', 'be', 'a', 'an', 'the'}:
        return 0.2, False
    if w in {'should', 'must', 'to', 'into', 'by', 'as', 'for', 'and', 'or'}:
        return -0.4, False
    if w in {'of', 'in', 'on', 'at', 'with', 'from', 'it', 'we', 'you', 'they'}:
        return -0.1, False
    if w in PUBLICATIONS:
        return 0.0, False
    if w in {'week', 'year', 'month', 'morning', 'season'}:
        return 0.4, False
    if not w or not any(c.isalpha() for c in w):
        return -0.2, False
    if text.startswith('.'):
        return -0.5, False
    if w.endswith(('tion', 'sion', 'ment', 'ness', 'ity')):
        return 0.85, False
    if w.endswith('s'):
        return 0.3, False
    if w.endswith('ed'):
        return 0.0, False
    if w.endswith('ing'):
        return 0.3, False
    return 0.4, False


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    text = prefix.token_strings[-1]
    word = text.strip()
    w = word.lower()
    reset = carry is None or carry[0] != doc
    value = 0.0
    if w == 'this':
        if reset:
            value = -1.5 if text.startswith(' ') else -0.4
        elif word[:1].isupper():
            value = 0.1
    if carry is not None and carry[0] == doc:
        previous, before = (x.strip() for x in carry[1:])
        trigger = previous.lower().lstrip('“\"\'>|.($')
        s, plural = strength(text)
        if trigger == 'this' and previous != 'THIS':
            value = -s * (0.28 if plural else 1.0)
            if previous[:1].isupper() and s > 0:
                value -= 0.22
            if (before.lower() in {'at', 'during', 'by'} and w in {'time', 'point'}
                    or before.lower() == 'in' and w == 'case'):
                value -= 0.5
            if before.lower() in {'solve', 'answer'} and w in {'problem', 'question'}:
                value -= 1.3
            if w == 'is' and before.endswith(('.', '!', '?')):
                value -= 0.15
            if word == '->':
                value = -2.25
        elif trigger == 'that':
            value = 0.12 - 0.49 * s if s >= 0.85 else 0.02
            if s < 0:
                value = 0.15 - 0.33 * s
            if w in {'was', 'are', 'were', 'can', 'will', 'would', 'has', 'have'}:
                value = 0.14
            if plural:
                value *= 0.2
            if w == 'is':
                value = -0.14
            if w == 'this':
                value = -0.48
        elif trigger in {'these', 'those', 'such'}:
            scale = {'these': 0.20, 'those': 0.13, 'such': 0.29}[trigger]
            value = 0.02 - scale * s
            if 0 < s < 0.85:
                value = -0.12 if trigger == 'these' else -0.06
            if trigger == 'such' and w in {'a', 'an'}:
                value = -0.2
            if w == 'are':
                value = -0.2 if trigger == 'these' else 0.1
        elif trigger in {'which', 'what', 'same'}:
            value = -{'which': 0.4, 'what': 0.16, 'same': 0.16}[trigger] * max(s, 0)
            if s < 1.4:
                value = 0.0
        elif (trigger in THIS_WORDS
              and (not previous.isascii() or carry[1].startswith(' '))):
            value = -0.7 * s
            if w in {'caso', 'случае'}:
                value = -2.5
        elif previous in ASIAN_THIS or previous == 'この':
            value = -0.55
            if word.startswith(('时', '時', '事', '点', '點', '类', '類',
                                '情况下', '場合', 'ように', 'くらい', '前')):
                value = -1.9
        elif w == 'of' and trigger in {'kind', 'type', 'sort'}:
            earlier = before.lower().lstrip('“\"\'>|.($')
            value = -2.0 if earlier == 'this' else -0.15
            if earlier == 'that':
                value = -0.7
    # Some Chinese tokens contain both demonstrative and referent.
    if word in {'这时', '這時', '此时', '此時', '此刻', '这一点', '這一點',
                '这时候', '這時候', '这个时候', '這個時候', '这一刻', '這一刻'}:
        value -= 1.6
    elif word in {'这种', '這種', '这一', '這一', '在这个', '在這個'}:
        value -= 0.75
    elif word in {'这', '這', '这个', '這個'}:
        value -= 0.28
    return (doc, text, carry[1] if not reset else ''), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 2313: the "this + noun" detector.

The component writes a negative value onto the word right after a demonstrative
"this" (or "This"). How negative depends on what that word is:

- a generic, situation-type noun ("this case", "this time", "this way", "this point",
  "this kind", "this reason", "this question", "this problem") is strongly negative;
- a copula or modal ("this is", "this was", "this can") is moderately negative;
- a document or punctuation token ("this article", "this paper", "this.", "this:") is about zero;
- any other word is weakly negative.

The same generic nouns after "that" or "which" are also negative, but less so
("that time", "which case"). Everything else is 0.
"""

READS = ()

GENERIC_NOUNS = set(
    "case time way point reason kind type question problem context situation "
    "moment matter issue topic information purpose option feature approach process "
    "method step area part particular country result action".split()
)
COPULA_MODAL = set("is was can will would means could should may might has does makes".split())
DOCUMENT_WORDS = set(
    "paper study article review blog post video page report website . , : ; ? ! -> ( )".split()
)


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    before = prefix.token_strings[-2].strip().lower()
    word = prefix.token_strings[-1].strip().lower()
    if before == "this":
        if word in GENERIC_NOUNS:
            return carry, -2.9
        if word in COPULA_MODAL:
            return carry, -1.05
        if word in DOCUMENT_WORDS:
            return carry, 0.0
        return carry, -0.4
    if before in ("that", "which") and word in GENERIC_NOUNS:
        return carry, -1.2
    return carry, 0.0

programs.sol:
"""A lexical detector for modifiers licensed by a definite noun phrase.

Look at the current token and its immediate predecessor. 'The' and possessives
strongly boost attributive modifiers, especially novelty and back-references;
'a/an', demonstratives and possessive endings give smaller boosts. Ordinals,
number words and productive adjective endings are handled explicitly. A small
negative response covers body/life nouns; 'from' has its own lexical response.
This approximates lexical classes, not a complete grammar or word tokenizer.
"""
READS = ()

POSSESSIVES = frozenset('my your our his her its their'.split())
ORDINALS = ('first', 'second', 'third', 'fourth', 'fifth', 'sixth',
            'seventh', 'eighth', 'ninth', 'tenth')
NUMBERS = frozenset('one two three four five six seven eight nine ten'.split())
BODY = frozenset('head eye eyes brain mind hand hands heart face mouth'.split())

# Semantic classes of attributive modifiers, with their definite-phrase strength.
CLASSES = (
    ('novelty', 2.2, 'new newly newfound proposed'),
    ('back_reference', 1.65,
     'previous former latter above aforementioned recent earlier '
     'recently previously given respective'),
    ('current_context', 1.3,
     'present current existing corresponding resulting intended provided '
     'observed selected chosen described stated supposed associated'),
    ('order', 0.85,
     'following next initial latest final remaining preceding prior'),
    ('time', 1.05,
     'early late old older later upcoming coming subsequent foregoing'),
    ('totality', 1.0, 'entire whole full overall original actual'),
    ('specificity', 1.0,
     'desired required specified particular additional specific usual'),
    ('change', 1.15, 'increased reduced improved enhanced growing combined'),
    ('degree', 0.85, 'very more much further'),
    ('size_comparison', 0.7,
     'long short higher lower better longer larger shorter smaller near'),
    ('description', 0.6,
     'great little special expected real free individual necessary '
     'single various relative common typical unique historic modern annual '
     'novel relevant different standard local general high small large big '
     'important regular official beautiful complete famous known available'),
    ('quantity', 0.3,
     'total many several numerous multiple main basic simple average default'),
    ('referential_nouns', 0.65, 'rest invention fact'),
)
CLASSES = tuple((name, strength, frozenset(words.split()))
                for name, strength, words in CLASSES)


def modifier_strength(word):
    if word in {'first', 'second'}:
        return 0.89
    if word in ORDINALS:
        return 0.43
    if word in NUMBERS:
        return 0.83 if word == 'two' else 0.33
    if word == 'last':
        return 0.67
    if word == 'other':
        return 1.2
    if word in {'now', 'increasingly', 'alleged'}:
        return 1.95
    if word in {'already', 'often', 'always'}:
        return 1.4
    for name, strength, words in CLASSES:
        if word in words:
            return strength
    if word.isalpha():
        # Productive adjective/adverb morphology; exclude common noun lookalikes.
        if word.endswith('ed') and word not in {
                'red', 'bed', 'speed', 'seed', 'need', 'feed'}:
            return 0.7
        if word.endswith('ly') and word not in {
                'family', 'supply', 'assembly', 'reply', 'anomaly', 'belly'}:
            return 0.8
        if word.endswith(('ous', 'ful')):
            return 0.4
        if word.endswith(('al', 'ive', 'able', 'ible')):
            return 0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word, prev = token.strip().lower(), previous.strip().lower()
    carry = (doc, token)

    if word == 'from':
        if token.strip() != 'from' or not token[:1].isspace():
            return carry, 0.56
        if '\n' in previous or previous.isspace():
            return carry, 0.46
        if prev in {'come', 'comes', 'came', 'coming', 'resulting'}:
            return carry, -0.1
        return carry, 0.2

    # Avoid treating subword suffixes as free-standing English words.
    boundary = not previous or token[:1].isspace() or previous[-1:].isspace()
    if not boundary:
        return carry, 0.0
    if prev == 'the':
        gate = 1.0
    elif prev in POSSESSIVES:
        gate = 0.95 if prev != 'her' else 0.75
    elif prev in {"'s", '’s'}:
        gate = 0.45
    elif prev in {'a', 'an'}:
        gate = 0.27
    elif prev in {'this', 'that', 'these', 'those'}:
        gate = 0.3
    else:
        gate = 0.0

    if word == 'own':
        return carry, 0.6 if prev in POSSESSIVES else 0.1
    if word == 'same':
        return carry, -0.4 + 0.54 * gate
    if word == 'life':
        return carry, -0.9 * gate
    if word in BODY:
        return carry, -0.5 * gate
    strength = modifier_strength(word)
    if token.strip()[:1].isupper():
        strength *= 0.65
    if word in {'new', 'newly', 'proposed'} and prev in {'a', 'an'}:
        gate = 0.21
    return carry, (0.1 if word == 'new' else 0.0) + gate * strength

programs.haiku:
"""Layer 0 MLP down_proj component 2314: fires on the word right after "the".

It is positive on a modifier that comes straight after a determiner and points at a
noun still to come, mostly ordinal, time-order or discourse-deictic words: "the new",
"the proposed", "the previous", "the above", "the present", "the following", "the first".
Strongest after "the" (and "The"), about half as strong after a, this, his, its, my...
Ordinary nouns after a determiner stay near zero. Predicts 0 everywhere else, except a
small value on "from" / "From".
"""

READS = ()

THE = {"the", "The"}
OTHER_DETERMINERS = {"a", "an", "this", "these", "those", "that", "his", "her", "its",
                     "my", "your", "our", "their"}
# Newness, recency and discourse reference: the noun is one already or just under discussion.
HIGH = {"new", "newly", "proposed", "previous", "above", "present", "current", "latter",
        "former", "aforementioned", "aforesaid", "foregoing", "respective", "given",
        "resulting", "corresponding", "specified", "intended", "desired", "existing",
        "observed", "other", "recent", "recently", "latest", "prior", "preceding"}
# Order and extent: first, second, next, last, the whole/entire part, the rest.
MEDIUM = {"first", "second", "third", "following", "next", "last", "final", "two",
          "entire", "whole", "original", "actual", "initial", "early", "late",
          "remaining", "rest", "overall", "usual", "old", "earlier", "later", "upcoming",
          "own", "particular", "specific", "certain", "subsequent", "incoming"}
TOP = {"new", "newly", "proposed", "previous", "above", "latter", "former", "aforementioned", "respective"}
PARTICIPLE_OR_ADJ_ENDINGS = ("ed", "al", "ous", "ive", "ic", "able", "ible", "ful", "ing")


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t - 1] != prefix.document_ids[t]:
        return carry, 0.0
    before = prefix.token_strings[t - 1].strip()
    word = prefix.token_strings[t].strip()
    if word in ("from", "From"):
        return carry, 0.2
    if before in THE:
        scale = 1.0
    elif before in OTHER_DETERMINERS:
        scale = 0.5
    else:
        return carry, 0.0
    if word in TOP:
        value = 1.8
    elif word in HIGH:
        value = 1.3
    elif word in MEDIUM:
        value = 0.9
    elif word.endswith(PARTICIPLE_OR_ADJ_ENDINGS) and word.islower():
        value = 0.25
    else:
        value = 0.0
    return carry, scale * value

programs.sol:
"""A detector for short 'le' spelling units, with a few related lexical signals.

It responds most to le and vowel+le fragments (especially ole), and to short
words with those endings. Whole long words such as people or table are not
matched just because they contain le. Plurals weaken the response. Whitespace,
capitalization and a punctuation boundary distinguish different spelling units.
Also recognized are le-like syllables in other scripts, the abbreviation <=,
Chinese gender/hole/role/sale words, and negative possibility adverbs.
This approximation uses only the current token, not hidden model computations.
"""
READS = ()


def token_value(token):
    spelling = token.strip()
    word = spelling.lower()
    boundary = bool(token and token[0].isspace())
    punct = bool(word and not word[0].isalnum())
    word = word.lstrip("._-/")
    upper = spelling.isupper()
    title = spelling[:1].isupper() and not upper

    # Small secondary signals: mathematical 'less or equal' and other scripts.
    if word in {"<=", "≤", "≦"}:
        return 0.65 if word == "<=" else 0.9
    if word in {"レ", "コレ", "勒"}:
        return 1.4
    if word in {"ле", "ľ", "เล", "레", "lé"}:
        return 0.85
    if word == "トレ":
        return 0.7
    if word in {"男", "男性", "男子", "雄"}:
        return 0.95
    if word == "女":
        return 0.7
    if word == "穴":
        return 1.9
    if word in {"洞", "角色", "主角", "售", "销售", "銷售"}:
        return 1.0
    if word in {"possibly", "potentially"}:
        return -0.95
    if word == "probably":
        return -0.4

    suffix = ""
    for ending in ("ly", "s", "d", "y"):
        if word.endswith("le" + ending):
            word, suffix = word[:-len(ending)], ending
            break

    value = 0.0
    if word == "le":
        value = 1.9 - 0.45 * boundary + 0.5 * punct
        if upper:
            value += 0.3
    elif len(word) == 3 and word.endswith("le"):
        onset = word[0]
        if onset == "o":
            value = 2.1 if upper else (3.6 if boundary else 4.25)
        elif onset == "a":
            value = 2.8 if boundary or title else 1.95
        elif onset == "e":
            value = 1.15 if boundary or title else 1.5
        elif onset in "iu":
            value = 2.0 if boundary else 1.35
        elif onset in "ylsd":
            value = 1.65
        elif onset == "k":
            value = 1.3
        elif onset in "cgfp":
            value = 1.0 + 0.8 * title
        elif onset in "bt":
            value = 0.5 + 0.4 * title
    elif len(word) == 4 and word.endswith("ole"):
        value = 2.25 if word[0] in "rh" else 3.9
        if word == "cole" and not boundary:
            value = 1.9
    elif len(word) == 4 and word.endswith("ale"):
        onset = word[0]
        if onset in "mdh":
            value = 3.0
        elif onset in "sb":
            value = 1.8 + 0.5 * title
        elif onset in "tgv":
            value = 1.3
        else:
            value = 0.7
    elif len(word) == 4 and word.endswith("ile"):
        value = 2.15 if word[0] == "m" else 0.8
