"""Assign positive scores to subword pieces ending in 'le' or 'les'.
The common 'ole' and 'ale'/'ile' endings get stronger scores than plain 'le'."""
READS = ()

def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1].strip().lower()
    if piece.endswith("ole"):
        value = 1.2
