programs.sol:
"""Approximate a weak, mostly token-specific early-layer signal.

The clearest formatting effects are negative on mixed tab/space whitespace
and positive on NUL tokens interleaved with letters (UTF-16-like text).
NUL-separated characters are distinguished as word starts or continuations;
other whitespace gets a small correction based on its character counts.
A few reliable word-family responses are added: forms of 'make' are negative,
and 'string(s)' is positive. Other lexical variation is not reconstructed.
"""
READS = ()
MAKE_FORMS = {"make", "makes", "made", "making"}
STRING_FORMS = {"string", "strings"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    content = '' if carry is None or carry[0] != doc else carry[2]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = -0.001

    if token == '\x00':
        if not previous:
            value = 0.026
        elif previous.isspace():
            value = -0.025
        elif previous.isalnum():
            vowel = len(previous) == 1 and previous.lower() in 'aeiou'
            value = 0.085 if vowel else 0.065
        else:
            value = 0.035
    elif previous == '\x00' and len(token) == 1:
        if token.isalnum():
            value = -0.05 if content.isspace() else 0.03
        elif token.isspace():
            value = -0.035 if content.isalnum() else 0.002
        else:
            value = -0.02
    elif word in MAKE_FORMS:
        value = -0.055
    elif word in STRING_FORMS:
        value = 0.073
    elif token.isspace():
        tabs = token.count('\t')
        spaces = token.count(' ')
        if tabs and spaces:
            value = -0.15 if spaces < 7 else -0.09
            if spaces >= 15:
                value = -0.05
        elif tabs and '\n' in token:
            value = -0.04
        elif tabs:
            value = -0.016 + 0.008 * tabs
        elif '\n' in token:
            value = 0.004 * token.count('\n') - 0.005 * bool(spaces)
        elif token.strip(' ') == '':
            value = -0.003 + 0.001 * spaces
        elif token.strip('\xa0') == '':
            value = 0.007 * (len(token) - 1)

    if token != '\x00':
        content = token
    return (doc, token, content), value

