    'custom': (-0.25, 'custom customary'),
    'customs': (-0.51, 'customs'),
    'tradition': (-0.08, 'tradition traditions traditional traditionally culture '
                  'cultures cultural practice practices practicing practiced'),
    'superstition': (-0.77, 'superst superstition superstitions superstitious'),
