    'chinese_customs': (-0.45, '俗 信仰 民俗 祭 祀'),
    'chinese_observance': (-0.34, '举行 节 節 祝 庆 慶 历 歷 供 拜 祈 忌 新年 '
                           '每年 每月 星期 纪念 紀念 禁忌'),
    'russian_holiday': (-0.55, 'празд праздник праздники'),
    'calendar': (-0.26, 'calendar calendars lunar gregorian julian leap'),
    'month': (-0.13, 'month'),
    'months': (-0.02, 'months monthly'),
    'week': (-0.01, 'week weeks weekly weekend weekends'),
    'day': (0.02, 'day days daily'),
    'year': (-0.04, 'year years annual annually yearly'),
    'season': (0.06, 'season seasons seasonal'),
    'seasons': (0.11, 'spring summer autumn winter'),
    'month_name': (0.04, 'january february march april may june july august september '
                    'october november december'),
    'weekday': (-0.02, 'monday tuesday wednesday thursday friday saturday sunday'),
}
LEXICON = {w: (g, value) for g, (value, words) in GROUPS.items() for w in words.split()}
EVENT = {'celebration', 'ceremony', 'festival', 'commemoration', 'holiday'}
TIME = {'month', 'months', 'week', 'day', 'year', 'season', 'seasons',
        'month_name', 'calendar'}
CULTURAL = {'religious', 'traditional', 'wedding', 'marriage', 'culture',
            'cultural', 'folk', 'birth', 'birthday', 'born', 'sacred', 'mythology'}
RELATIVE = {'last', 'next', 'past', 'previous', 'recent', 'this', 'that'}
CALENDAR = {'calendar', 'month', 'months', 'day', 'days', 'leap', 'date'}
CULTURE_SENSITIVE = EVENT | {'calendar', 'tradition', 'folklore', 'religion',
                             'month', 'month_name'}
STEMS = {'celebr', 'commemor', 'commem', 'superst', 'празд'}
SUFFIXES = {'ate', 'ates', 'ated', 'ating', 'ation', 'ations', 'ition',
            'ities', 'ники', 'ant', 'ants'}


def group_of(word):
    return LEXICON.get(word, (None, 0.0))[0]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous = [], ''
    else:
        _, history, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    group, response = LEXICON.get(word, (None, 0.0))
    boundary = not previous or token[:1].isspace() or not previous[-1:].isalpha()
    if (word.isascii() and not boundary) or (word == 'may' and token.strip() != 'May'):
        group, response = None, 0.0
    value = -0.0017 + response
    recent, last = history[-8:], history[-1] if history else ''
    if group is not None and not history:
        value -= 0.23
    if group in CULTURE_SENSITIVE:
        if any(group_of(w) in EVENT or w in CULTURAL for w in history):
            value -= 0.11
    if group in TIME:
        if any(group_of(w) in EVENT or w == 'lunar' for w in recent):
            value -= 0.28
        if any(w in CALENDAR for w in recent):
            value -= 0.14
        if any(w in RELATIVE for w in history[-3:]):
            value += 0.11
        if last == 'past':
            value += 0.34
        if last in {'every', 'each'}:
            value -= 0.12
        if group in {'day', 'season'} and 'rainy' in history[-2:]:
            value -= 0.56
        if group == 'season' and any(w in {'holiday', 'festive'} for w in history[-2:]):
            value -= 0.67
        if group == 'year' and last == 'new':
            value -= 0.19
        if group == 'month_name' and any(group_of(w) == 'weekday' for w in history[-4:]):
            value -= 0.41
    if group in {'ceremony', 'celebration'} and any(
        w in {'wedding', 'marriage', 'religious', 'traditional'} for w in recent
    ):
        value -= 0.42
    if group == 'festival' and 'film' in history[-3:]:
        value += 0.35
    if word in {'of', 'the', 'a', 'to'} and group_of(last) in EVENT:
        value -= 0.29 if word == 'of' else 0.13
    if not token[:1].isspace() and (
        (word in SUFFIXES and last in STEMS) or (word == 'brate' and last == 'cele')
    ):
        value -= 0.39
    history = (history + [word])[-16:]
    return (doc, history, token), float(value)

