STRENGTH = 0.3
CELEBRATION = ("celebrat", "festiv", "holiday", "ceremon", "feast", "commemor", "празд", "ritual")
CALENDAR = {"calendar", "season", "december", "november", "september", "christmas", "thanksgiving", "leap"}
TRADITION = ("folklore", "mytholog", "legend", "pagan", "superst", "taboo", "sacrific", "practice", "cultur", "tradition")
WEAK = {"day", "year", "month", "week", "months"}

def step(carry, prefix, upstream):
