"""Approximate a local noun/grammar contrast, not the full lexical response.

Abstract and mass nouns tend positive after articles or possessives, negative
following prepositions or conjunctions. Semantic families set a baseline and
contrast strength. Smaller rules cover quantifiers, qualification, familiar
relational phrases and conversation markup. State resets at document changes.
"""

READS = ()

# Named semantic families: token strings, neutral response, grammar strength.
NOUNS = {
    'fields of inquiry': (
        set('science physics mathematics chemistry philosophy'.split()),
        .05, .31,
    ),
    'cultural knowledge': (
        set('art music literature history language technology'.split()),
        -.013, .246,
    ),
    'abstract universals': (
        set('''death truth religion reason nature god reality beauty peace
freedom knowledge wisdom friendship virtue faith justice perception
consciousness morality happiness'''.split()), -.053, .286,
    ),
    'feelings and conditions': (
        set('''pain fear love joy emotion anger health danger doubt suffering
pleasure shame grief hope'''.split()), .037, .184,
    ),
    'substances and quantities': (
        set('''time life light water space money matter energy food information
work power heat air blood education'''.split()), -.001, .134,
    ),
    'human activities': (
        set('war violence murder worship'.split()), -.018, .262,
    ),
    'supernatural concepts': (
        set('hell magic fantasy'.split()), .132, .287,
    ),
    'technical subjects': (
        set('finance algebra geometry engineering'.split()), .081, .168,
    ),
}
ARTICLES = set('the a an'.split())
POSSESSIVES = set('my your his her our their its'.split())
RELATIONS = set('''of to in on with for by from about through between
against into over without as and or is are was were be'''.split())
VERTICAL = set('up down above below top bottom lower upper'.split())
QUALIFICATIONS = set('''significant significantly important importantly relevant
likely unlikely available supported useful real additional'''.split())


def grammar(previous):
    if previous in ARTICLES:
        return 1.0
    if previous in POSSESSIVES:
        return .7
    if previous in RELATIONS:
        return -.7
    if previous in {',', '.', ';', ':'}:
        return -.35
    if previous in {'this', 'these', 'those', "'s", '’s'}:
        return .3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = -.0005

    if token.startswith(' ') or first:
        for family, neutral, strength in NOUNS.values():
