            if word.isalpha() and len(word) > 5:
                if word.endswith(('ness', 'ity', 'tion', 'ment', 'ence', 'ism')):
                    value = -.004 + .032 * grammar(previous)

    if word in {'how', 'where', 'why'}:
        value = -.04
    elif word in VERTICAL:
        value = -.075 if previous == 'the' else -.04
    elif word in {'together', 'apart'}:
        value = -.08
    elif word in QUALIFICATIONS:
        value = -.06
    elif word in {'one', 'every', 'whole'}:
        value = -.055
    elif word in {'several', 'few'}:
        value = .065
    elif word in {'both', 'either', 'neither'}:
        value = .035
    elif word in {'but', 'also'}:
        value = .04
    elif word == 'own':
        value = .06
    elif word == 'respect':
        value = -.17 if previous == 'with' else -.07
    elif word == 'of' and previous in {'part', 'type', 'out', 'instead'}:
        value = -.055
    elif word == 'of' and previous in {'instance', 'member'}:
        value = .065
    elif word == 'to' and previous == 'how':
        value = -.09
    elif word in {'with', 'to'} and previous == 'compared':
        value = .08
    elif word == 'with' and previous == 'associated':
        value = -.06
    elif token in {'<think>', '</think>'}:
        value = .08 if token == '<think>' else -.09
    elif token == '<|im_end|>':
        value = -.095 if previous == '</tool_call>' else -.05
    elif token == '<|im_start|>':
        value = .103 if first else -.007
    elif token in {'<tool_call>', '</tool_call>'}:
        value = .03 if token == '<tool_call>' else -.04
    elif token in {'<tool_response>', '</tool_response>'}:
        value = .013 if token == '<tool_response>' else -.022
    elif token.isspace() and previous in {'<think>', '</think>'}:
        value = .02 if previous == '<think>' else .038
    elif word == 'the' and first:
        value = .085
    elif token == 'The':
        value = .03
    return (doc, word), float(value)

"""A lexical detector for identity, recognition, and encounters/incidents.

Identity stems and accident/incident words activate strongly. Seeing, discovery,
and situations activate less; Chinese 遇 (encounter) is especially strong. The
few phrase rules handle split identity words, recognition nouns followed by
"of", possibility contrasts, and seeing something in an if/when clause. This
is a local spelling/phrase approximation, not general semantic understanding.
Strong training responses cluster around these word families; unlisted text is
zero, apart from the explicitly listed phrase continuations.
"""
READS = ()

# Related vocabulary shares a response; these are words, not token IDs.
WORD_CLASSES = (
    (0.6, 'seen saw seeing sees'),
    (0.65, 'situation situations whenever'),
    (0.42, 'scenario scenarios circumstances happen happens happened occurrence'),
    (0.8, 'adjacent acent acency incidence incid'),
    (0.3, 'face faces facing detect detected detection'),
    (0.75, 'faced'),
    (0.18, 'found meet meeting meets meetings noticed happening'),
    (0.45, 'rare exception overlap overlapping discover discovered discovery'),
    (0.4, 'opportunities victims injuries injury'),
    (-0.15, 'possible impossible available'),
)
WORD_VALUES = {word: value for value, words in WORD_CLASSES
               for word in words.split()}

# Chinese/Japanese encounter, identity and perception vocabulary.
EAST_ASIAN_CLASSES = (
    (3.0, {'遭遇', '遇上', '相遇'}),
    (3.5, {'遇见', '遇見', '碰到', '遇到了'}),
    (2.6, {'逢', '每逢', '碰', '撞'}),
    (2.1, {'机遇', '機遇', '事故', '重大', '应急', '應急'}),
    (1.8, {'识别', '識別'}),
    (1.2, {'见', '見', '见到', '识', '識', '身份', '一旦', '出会い'}),
    (1.0, {'意识', '身份证', '待遇', '碰撞', '撞击'}),
    (0.7, {'意識', '看到', '看见', '看見', '见面', 'を見', '出现', '出現',
           '发生', '發生', '发现', '發現', '发现了', '出会', '看到了',
           '见过', '見て', 'を見て', '面对', '面對', '意外', '遭', '遭受'}),
)
EAST_ASIAN_VALUES = {word: value for value, words in EAST_ASIAN_CLASSES
                    for word in words}


def lexical(raw):
    word = raw.strip().lower()
    stem = word.lstrip('._(/')  # Identity names also occur in code.
    spaced = raw.startswith(' ')
    if stem.startswith('ident'):
        if stem == 'ident':
            if raw.strip() == 'IDENT' and not spaced:
                return 0.9
            return 3.2 if spaced and raw.strip() == 'ident' else 2.8
        if stem == 'idential':
            return 0.4
        if stem.startswith('identical'):
            return 0.8
        if stem.startswith('identifier') or stem == 'identifiable':
            return 1.1 if spaced or word.startswith('.') else 0.8
        if stem in {'idental', 'idents', 'idente'}:
            return 1.3
        if stem in {'identity', 'identities'}:
            return 2.1 if spaced or word.startswith('_') else 1.6
        return 2.15 if stem == 'identify' else 1.9
    if word.startswith('accident'):
        return 0.9 if word == 'accidentally' else 1.8
    if word.startswith('incident'):
        return 1.4 if word == 'incidental' else 2.5
    if word.startswith('encounter'):
        return 1.7
    if word.startswith('rencontr'):
        return 1.4
    if word.startswith(('encontr', 'incontr', 'встреч')):
        return 0.85
    if word == 'gặp':
        return 2.2
    if word.startswith(('collis', 'collid')) or word == 'ollision':
        return 1.2
    if word in {'emergency', 'emergencies'}:
        return 1.1
    if word == 'see':
        return 0.44 if raw == ' see' else 0.25
    if word.startswith('recogn'):
        return 0.85 if word == 'recognition' else 0.5
    if word in {'遇', '遇到'}:
        return 6.7 if word == '遇' else 5.3
    return WORD_VALUES.get(word, EAST_ASIAN_VALUES.get(word, 0.0))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, before = carry[1:] if carry and carry[0] == doc else ('', '')
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = lexical(raw)

    # Recognize words even when the tokenizer splits stem and ending.
    if not raw[:1].isspace():
        if prev.lstrip('._(/') == 'ident':
            if word in {'ify', 'ifying', 'ification', 'ity', 'ities'}:
                value = 2.45 if word == 'ify' else 2.0
            elif word in {'ical', 'iques'}:
                value = 0.8
        if word in {'ident', 'idents'}:
            joined = prev + word
            if any(root in joined for root in ('resident', 'president',
                   'confident', 'dissident', 'résident', 'président', 'präsident')):
                value = 1.1 if word == 'ident' else 0.6
            elif joined.endswith(('occident', 'coincident')):
                value = 2.0
            elif joined.endswith(('accidents', 'incidents')):
                value = 2.2

    if raw == ' of':
        if prev in {'identity', 'identities', 'identification'}:
            value = 1.15
        elif prev in {'incident', 'incidents', 'accident', 'accidents'}:
            value = 1.5
        elif prev in {'case', 'cases', 'occurrence', 'incidence',
                      'discovery', 'handling', 'victims'}:
            value = 0.55
        elif prev in {'one', 'kind', 'type', 'example', 'instead', 'risk'}:
            value = -0.2
    if raw == ' to' and prev in {'possible', 'impossible'}:
        value = -0.62
    if raw == ' from' and prev in {'apart', 'different'}:
        value = -0.45
    if raw == ' see' and prev in {'i', 'you', 'we', 'they'}:
        value = 0.9 if before == 'when' else 0.8 if before == 'if' else 0.67
    if word in {'happens', 'happen'} and prev in {'this', 'that', 'it', 'which'}:
        value = 1.0 if before == 'when' else 0.7

    # Only byte-split characters need the cumulatively decoded text.
    if '�' in raw and prev:
        completed = prefix.text_prefixes[-1][-1:]
        if completed in {'遇', '逢', '碰', '撞', '见', '見', '识', '識'}:
            value = lexical(completed)
    return (doc, word, prev), float(value)

