"""Mark words about perception, recognition, and the situations they reveal."""
READS = ()

# Recognition and identity words tend to be the strongest positive examples.
RECOGNITION = (
    "ident", "recogniz", "recognis", "credential", "识",
)
PERCEPTION = (
    "see", "saw", "seen", "view", "look", "watch", "observ", "notic",
    "perceiv", "detect", "aware", "conscious", "意识", "看到", "見",
)
