    upper = previous.isupper()
    plain = unicodedata.normalize('NFD', previous.lower())[:1]
    vowel = bool(plain) and plain in 'aeiouy'
    repeated = previous.lower() == 'g'
    digit = previous.isdigit()
    whitespace = s[:1].isspace()
    piece = s.lstrip() if whitespace else s
    punct = bool(piece) and not piece[0].isalnum()
    if punct:
        piece = piece[1:]
    n = len(piece)
