    if piece.lower().startswith('georg'):
        return carry, -0.75
    if s == 'js':  # JavaScript abbreviation, without a dot in the token
        return carry, float(0.45 + 0.23 * alpha - 0.10 * vowel)
    # Related g/j spellings in other alphabets.
    if piece and piece[0] in 'гГγΓگغجグジ' and n <= 3:
        if whitespace:
            value = -0.30
        elif piece[0] in 'гГ':
            value = 0.15 + 0.40 * alpha + 0.27 * upper
            if n > 1:
                value += 0.28
        elif piece[0] in 'γΓ':
            value = 0.10 + 0.18 * alpha
        else:
            value = 0.15 + 0.20 * alpha
        return carry, float(value)
