    if piece.isalpha() and n == 2 and piece.endswith(('g', 'G')):
        if piece[0].lower() not in 'aeiouynmg':
            value = -0.40 if piece[-1] == 'G' else -0.30
            return carry, float(value - 0.25 * repeated)
        if piece[-1] == 'G' and piece[0] != 'G':
            return carry, -0.12

    if not piece or piece[0] not in 'gG':
        return carry, -0.002

