            value = -0.20 + 0.06 * alpha + 0.12 * upper + 0.05 * vowel
        elif punct:
            value = -0.35 + 0.05 * alpha + 0.24 * upper + 0.32 * vowel
        else:
            value = (-0.12 + 0.66 * alpha + 0.55 * upper
                     + 0.11 * vowel - 0.34 * repeated + 0.16 * digit)
        if position == 0:
            value = -0.98
    elif whitespace:
        if piece[0] == 'g':
            value = (-0.03 + 0.10 * alpha + 0.14 * upper
                     + 0.04 * vowel - 0.05 * repeated)
        elif piece.isupper():
            value = 0.07 if n == 2 else -0.23 if n == 3 else 0.0
            value += 0.16 * upper
        else:
            value = (-0.10 if n >= 4 else 0.0) + 0.08 * alpha + 0.13 * upper
    elif punct:
        value = 0.08 if n == 2 else 0.0
    elif piece[0] == 'g' and piece.isalpha():
