                     + 0.29 * vowel - 0.55 * repeated)
        else:
            value = 0.05 + 0.30 * alpha + 0.12 * vowel - 0.20 * repeated
    elif piece.isupper():
        value = 0.23 if n == 2 else -0.30 if n == 3 else -0.10
        value += (0.61 if n == 2 else 0.40) * alpha + 0.40 * upper
    else:
        value = -0.12 + 0.21 * alpha + 0.10 * upper + 0.10 * vowel
