    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ""
    else:
        tail = carry[1]
    token = prefix.token_strings[-1]
    context = tail + token
    stripped = token.strip()
    left = tail.rstrip()
    before = left[-1:] if left else ""
    after = stripped[1:] if stripped else ""
    mark = next((ch for ch in stripped if ch in (
        _PLUS | _MULTIPLY | _DIVIDE | _CARET | _DASH | _ARROWS | {"±"}
    )), "")

    value = 0.0
    word = stripped.lower()
    if word in {"and", "to"} and _digit(before):
        value = 0.55 if word == "and" else 0.85
    elif not stripped and token and token.isspace() and _digit(before):
        value = 0.2
    elif mark in _PLUS:
        value = 2.7
    elif mark in _MULTIPLY:
        value = 1.0
    elif mark in _DIVIDE:
        value = 1.0
    elif mark in _CARET:
        value = 1.1
    elif mark == "±":
        value = 0.5
    elif mark in _ARROWS:
        value = 0.35
    elif mark in _DASH:
        if _digit(before):
            value = 2.4
        elif before and before.isalpha() and after and after[0].isalpha():
            value = -0.45
        elif stripped.startswith(mark) and len(stripped) > 1 and stripped[1:].isalpha():
            value = -0.35
        else:
            value = -0.35 if token != stripped else -0.2
        if mark in _DASH and not _digit(before):
            line_start = tail.rsplit("\n", 1)[-1]
            if not line_start.strip() or before == ">":
                value = -0.8

    new_tail = context[-100:]
    return (doc, new_tail), float(0.45 * value)

programs.sol:
"""Negative lexical response centered on 'are', 'were', and short -are forms.

This is mainly a spelling detector, not a test for a plural subject: bare,
care, rare and fragments such as 'ares' also respond. Short attached 'are'
endings respond more than endings of long words. Capitalization strengthens
many of these responses. Neighboring pronouns and clause-linking words
adjust the copulas.
A few other forms of 'be' have weaker responses.
"""
import re

READS = ()

BE_FORMS = {
    'was': -0.185, 'am': -0.31, 'be': -0.06,
    "'re": -0.49, '’re': -0.49, "'m": -0.35, '’m': -0.35,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lstrip("-")
    low = word.lower()
    capital = bool(word) and word[0].isupper()
    attached = bool(token) and not token[0].isspace()
    value = -0.001
    if low == 'are':
        if attached and not capital:
            if tail:
                value = -4.3 + 0.42 * min(len(tail), 6)
                if tail[0].isupper():
                    value -= 0.75
            else:
                value = -2.95
        else:
            if word.isupper():
                value = -3.9 if attached else -3.0
            else:
                value = -2.13 if capital else -1.92
    elif low == 'were':
        value = -2.15 if capital or attached else -1.83
    elif low in {'aren', 'weren'}:
        value = -1.5 if low == 'aren' else -1.2
        if attached or capital:
            value -= 0.5
    # Short -are words, but not the much weaker share and square families.
    elif (len(low) in {4, 5} and low.endswith('are')
          and low[0] not in 'aeiou' and low not in {'share', 'quare'}):
        value = -3.4 if len(low) == 4 else -2.15
        if low == 'care':
            value = -2.75
        elif low in {'fare', 'ware'}:
            value = -2.1
        if capital:
            value -= 0.5
        if token.startswith('-'):
            value -= 0.4
    elif low.startswith('are') and 3 < len(low) <= 5 and low not in {'area', 'areas'}:
        value = -2.35 if low == 'ares' else -1.15
    elif low == 'aring':
        value = -1.65
    elif low in {'cares', 'cared', 'caring'}:
        value = -2.2
    elif low in {'rarely', 'aware', 'awareness'} or low.endswith('healthcare'):
        value = -0.9 if low != 'rarely' else -1.3
    elif low == 'mere':
        value = -2.0
    elif low.endswith('ere') and len(low) <= 4 and low != 'here':
        value = -0.6
    elif low in BE_FORMS and (not attached or low.startswith(("'", '’'))):
        value = BE_FORMS[low]
    # Ordinary separated copulas are weaker after we/you or existential there,
    # and stronger after a coordinating word or which/what.
    if low in {'are', 'were'} and not attached and not capital:
        previous = tail.lower()
        if previous in {'we', 'you', 'there'}:
            value += 0.45
        elif previous in {'who', 'that', 'these'}:
            value += 0.2
        elif previous == 'they' and low == 'were':
            value += 0.18
        elif previous in {'and', 'or', 'but', 'which', 'what'}:
            value -= 0.3 if low == 'are' else 0.22
    match = re.search(r'[A-Za-z]+$', (tail + token)[-40:])
    tail = match.group() if match else ''
    return (doc, tail), float(value)

