"""Layer-0 MLP down-projection component 2330: a word detector for the sound "are".

The component pushes the residual stream strongly negative on the word "are" and its
relatives "were", "aren't" and "weren't" (plural and second-person forms of "to be"), and
on single words that rhyme with "are": care, rare, bare, dare, spare, stare, fare, scare...
It is near zero on everything else, and weakly negative on the contraction "'re" and on
" am". It reads only the current token, so it is a lookup by spelling, not a context rule.
"""

READS = ()

ARE_FORMS = {"are", "were", "aren", "weren", "arent", "ares"}
ARE_RHYMES = {"care", "cares", "rare", "bare", "dare", "pare", "hare", "mare", "fare",
              "ware", "spare", "stare", "flare", "scare", "aware", "clare"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower().replace("’", "'")
    if word in ARE_FORMS:
        value = -1.9
    elif word in ARE_RHYMES:
        value = -2.8
    elif word == "'re":
        value = -0.5
    elif token == " am":
        value = -0.3
    else:
        value = 0.0
    return carry, value

