"""Estimate activation from successive letter pieces within one word."""
import unicodedata

READS = ()


def letter(text):
    return bool(text) and unicodedata.category(text[0])[0] == "L"


def script(character):
    name = unicodedata.name(character, "")
    for family in ("LATIN", "CYRILLIC", "ARABIC", "GREEK", "HIRAGANA"):
        if family in name:
            return family
    return "other"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.lstrip()
    first = text[:1]
    family = script(first) if first else "other"

    continues_word = False
    if (len(prefix.token_strings) > 1 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
        continues_word = (
            token and not token[0].isspace()
            and letter(first) and letter(previous[-1:])
        )

    if family == "LATIN":
        if continues_word:
            length = len(text)
            if length == 1:
                value = 0.16
            elif length <= 4:
                value = 0.21
            elif length == 5:
                value = 0.13
            else:
                value = 0.06
        else:
            value = -0.004
    elif family == "CYRILLIC":
        if continues_word:
            length = len(text)
            if length == 1:
                value = 0.22
            elif length == 2:
                value = 0.41
            elif length == 3:
                value = 0.51
            else:
                value = 0.41
        else:
            value = -0.08
    elif family == "ARABIC":
        value = 0.47 if continues_word else -0.06
    elif family == "GREEK":
        value = 0.09 if continues_word else -0.05
    elif family == "HIRAGANA":
        value = 0.06 if continues_word else 0.0
    else:
        value = 0.0
    return None, value

"""Approximate responses to message-end and visible escape markers.

A chat end marker gets a strong positive signal. In a visible backslash escape,
the `n` or `t` marker gets a positive signal too; longer tokens beginning with
`n` are treated less strongly than the standalone marker.
"""

READS = ()
CHAT_END = "<|im_end|>"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == CHAT_END:
        return None, 1.84

    if prefix.position:
        previous = prefix.token_strings[-2]
        if previous.endswith("\\"):
            if token == "n":
                return None, 1.30
            if token.startswith("n"):
                return None, 0.90
            if token == "t":
                return None, 0.80
        if token.startswith("\\") and token[1:2] in ("n", "t"):
            return None, 0.45

    return None, 0.0

programs.sol:
"""Approximate the strong negative response to Thai consonant-led fragments.

Vowel/tone continuations are weaker. Broad Thai sound groups, a preceding
vowel/mark, onset clusters and token length refine the estimate. A space
immediately after Thai also gets a negative value. Myanmar letters and chat
boundaries have smaller responses. Most other tokens are left at zero;
byte fragments and idiosyncratic word effects are not modelled.
"""

import unicodedata

READS = ()
# Letters, isolated, after vowel/mark, word-initial, after preposed vowel.
SOUND_GROUPS = (
    ('ง', -1.3, -0.1, -1.4, -0.6),             # velar nasal
    ('ญณนม', -2.7, -1.4, -1.8, -1.6),         # other nasals
    ('รลฬ', -4.6, -3.5, -1.8, -0.7),          # liquids
    ('ยว', -4.1, -2.6, -0.9, -0.5),           # glides
    ('ขคฆฉชฌถทธผพภ', -5.0, -4.0, -2.2, -1.0),  # aspirated
    ('กจฎฏดตบป', -4.0, -3.0, -2.2, -0.6),     # plain stops
    ('ซศษสฝฟ', -4.1, -3.2, -2.6, -0.6),       # fricatives
    ('หฮ', -4.4, -3.9, -2.8, 0.4),            # h
    ('อ', -4.7, -1.9, -2.2, -0.3),            # vowel carrier
    ('ฃฅฐฑฒ', -1.2, -1.1, -0.5, -0.6),       # obsolete / retroflex letters
)
CONSONANTS = ''.join(row[0] for row in SOUND_GROUPS)
MARKS = 'ัิีึืุู็่้๊๋์ํ๎'
SPACING_VOWELS = 'ะาำๅ'
PREPOSED = {'เ': -1.8, 'แ': -1.5, 'โ': -0.8, 'ใ': -1.7, 'ไ': -1.2}
ONSET_CLUSTERS = set(
    'กร กล กว ขร ขล ขว คร คล คว ตร ปร ปล พร พล ผล ทร '
    'หง หญ หน หม หย หร หล หว อย'.split()
)
FINAL_STOPS_LIQUIDS = 'กขคฆจชซฎฏฐฑฒดตถทธศษสบปพฟภรล'


def sound_group(c):
    for row in SOUND_GROUPS:
        if c and c in row[0]:
            return row
    return ('', -0.5, -0.5, -1.0, -1.4)


def thai_value(s, previous):
    c = s[0]
    if c in MARKS:
        value = -0.83
        if c in '่้๊๋':
            value += 0.22
        if c in '็์':
            value += 0.23
        if c in 'ืุู':
            value -= 0.09
        if s.startswith('ี่'):
            value += 0.74
        if c in '่้' and s.endswith('ว'):
            value -= 0.83
        return value
    if c in SPACING_VOWELS:
        value = -1.35
        if len(s) > 1 and s[-1] in FINAL_STOPS_LIQUIDS:
            value -= 1.3
        return value
    if len(s) == 1 and c in CONSONANTS:
        after_vowel = previous and previous[-1] in MARKS + SPACING_VOWELS + 'อ'
        return sound_group(c)[2 if after_vowel else 1]
    leading = c in PREPOSED
    stem = s[1:] if leading else s
    first = next((ch for ch in s if ch in CONSONANTS), '')
    value = sound_group(first)[4 if leading else 3]
    if leading:
        value += PREPOSED[c]
    value += 0.67 * max(0, min(6, len(s)) - 2)
    value -= 0.56 * min(2, sum(ch in SPACING_VOWELS for ch in s))
    if s[-1] in CONSONANTS:
        value -= 1.17
    if stem[:2] in ONSET_CLUSTERS:
        value -= 0.82
    if stem[:2] in ('อง', 'อน', 'อม'):
        value += 2.0
    if 'ำ' in s:
        value -= 0.86
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    s = raw.strip()
    if s and ('\u0e01' <= s[0] <= '\u0e3a' or s[0] in MARKS + 'เแโใไๅ'):
        value = thai_value(s, previous)
    elif raw == ' ' and any('\u0e01' <= ch <= '\u0e5b' for ch in previous):
        value = -0.64
    elif s and '\u1000' <= s[0] <= '\u109f':
        value = -2.0 if unicodedata.category(s[0]).startswith('L') else -0.2
        if s[0] in 'ငည':
            value = -1.0
    elif raw == '<|im_end|>':
        value = -0.6 if previous in ('</tool_call>', '</tool_response>') else -0.35
        if not previous:
            value = -0.84
    elif raw == '<|im_start|>':
        value = 0.13
    elif raw == '<tool_response>':
        value = -0.36
    elif raw == '</think>':
        value = -0.29
    else:
        value = 0.0
    return (doc, raw), float(value)

