"""Layer-0 MLP component 2334 (down_proj) is a "back-reference" detector. It goes negative on
words that point to something earlier in a sequence or in time: "previous(ly)", "prev",
"prior", "past", "earlier", "preceding", "subsequent", "consecutive", "successive". It goes
slightly negative on "adjacent", "parent", and "neighbor(ing)". On every other token it is near
zero, so the program predicts 0 there. The program is a lookup on the newest token alone (no
carried state): each word class gets its typical activation, measured on training text.
"""

READS = ()

# Typical activation of each word class (measured means: previous about -5.6, prior -1.7,
# past -1.4, earlier -0.9, subsequent -1.9, adjacent -0.7, parent -0.7).
PREVIOUS_WORDS = {"previous", "previously"}
ABBREVIATION = "prev"
EARLIER_WORDS = {
    "prior", "past", "earlier", "preceding", "subsequent", "subsequently",
    "consecutive", "successive", "anterior", "formerly",
}
NEARBY_WORDS = {"adjacent", "parent", "neighbor", "neighboring", "neighbors"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().lstrip("(\t._\"'")
    if word in PREVIOUS_WORDS:
        return None, -5.5
    if word == ABBREVIATION:
        return None, -3.9
    if word in EARLIER_WORDS:
        return None, -1.4
    if word in NEARBY_WORDS:
        return None, -0.6
    return None, 0.0

