"""Approximate activation from written syllables, without decoding pronunciation.

Short Cyrillic fragments ending in я (ya) dominate, with weaker responses to
ю (yu), ё (yo), soft signs and vowel endings. The preceding letter changes
the strength of a syllable; longer fragments dilute it. Reflexive -ся and
the preposition для have separate rules, as does the яв- stem. A few other
scripts' ya spellings also respond. Most lexical and contextual variation
is intentionally omitted; unmatched tokens receive zero.
"""
READS = ()

# The sound immediately before final я changes the strength of that syllable.
BEFORE_YA = {'а': 2.6, 'и': 1.9, 'о': 3.7, 'ь': 2.9,
             'л': 3.5, 'р': 3.6, 'с': 1.4, 'н': 1.8,
             'т': 3.0, 'м': 2.9}
BEFORE_YU = {'у': 1.6, 'л': 1.8, 'н': 1.3, 'ь': 1.2, 'и': 0.8}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    s = token.strip().lower()
    n = len(s)
    value = 0.0
    if n and all('\u0400' <= c <= '\u04ff' for c in s):
        word_start = token[0].isspace()
        if s == 'я':
            value = 4.05
        elif s.startswith('яв'):
            value = 1.2
        elif n > 2 and s.endswith('ся'):
            value = 1.1 / n ** 0.5
        elif s.endswith('я'):
            value = BEFORE_YA.get(s[-2], 2.1) * (2 / n) ** 1.25
            if s == 'оля':
                value = 3.8
            elif s == 'еля':
                value = 2.5
            if word_start:
                value *= 0.75
            if s == 'для':
                value = 0.55
        elif s.endswith('ю'):
            value = 1.55 if n == 1 else BEFORE_YU.get(s[-2], 1.0)
            if n > 2:
                value *= (2 / n) ** 1.3
            if word_start and n > 1:
                value *= 0.7
        elif 'я' in s:
            value = 1.4 / n ** 0.6
        elif 'ю' in s:
            value = 0.8 / n ** 0.7
        elif s == 'ё':
            value = 0.75
        elif s == 'ь':
            value = 0.8
        elif s == 'ъ':
            value = 0.5
        elif not word_start:
            if s.endswith('ей'):
                value = 1.5 / n ** 0.9
            elif s.endswith('ий'):
                value = 1.0 / n ** 1.3
            elif s.endswith('а'):
                value = 0.35 if n == 1 else 0.7 / n ** 0.4
                if n >= 3 and s[-3] in 'ио' and s[-2] in 'нк':
                    value += 0.3
            elif s.endswith('ь') and not s.endswith('ть'):
                value = 0.5 / n ** 0.6
            elif s == 'ие':
                value = 0.8
    elif s in ('ya', 'ja', 'ia'):
        value = {'ya': 0.5, 'ja': 0.7, 'ia': 0.3}[s]
    elif n == 3 and not token[0].isspace() and s.endswith(('ya', 'ja', 'ia')):
        value = 0.4
    elif s in ('や', 'ヤ', 'ゃ', 'ャ', 'イヤ'):
        value = 1.5 if s == 'ヤ' else 1.0 if s == 'イヤ' else 0.35
    elif s in ('亚', '亞', '雅', '牙', 'يا'):
        # Chinese ya characters and Arabic ya.
        value = 0.6
    elif n == 1 and '\uac00' <= s <= '\ud7a3':
        # Unicode Hangul: open syllables with vowels ya or yeo.
        syllable = ord(s) - 0xac00
        if syllable % 28 == 0 and (syllable // 28) % 21 in (2, 6):
            value = 0.65
    return None, float(value)

programs.haiku:
"""Cyrillic "я" detector (layer-0 MLP down_proj, component 2337).

The component writes its contribution mainly when the current token carries the sound
"ya", above all the Russian letter я (Я). It is strongest when the token is the bare
letter (the pronoun "я"), a bit weaker on word pieces that end in я (ля, ая, ия, ня, ...),
and weaker still on other endings. Latin transliterations ("ja", "ya") and the
Japanese/Korean "ya" syllables (ヤ, や, 야) get a moderate value. Everything else is 0.

The program reads only the newest token (the last entry of `prefix.token_strings`), so it
is causal and needs no carry. Values are the typical activation for each class, read off
training rows.
"""

import re

READS = ()

CYRILLIC_WORD = re.compile("[а-я]+")


def value_of(token):
    x = token.strip().lower()
    if x == "я":
        return 4.0
    if x == "ля":
        return 3.4
    if x.endswith("я"):
        return 2.5  # word pieces ending in я: ая, ия, оя, ня, ...
    if x.endswith(("ю", "ся")):
        return 1.2  # ю and the reflexive -ся
    if x.endswith(("ь", "ей", "ка")):
        return 0.7
    if x.endswith(("ya", "ja")) or x == "yan":
        return 0.6  # Latin transliterations of я
    if x in ("ヤ", "や", "야", "ャ"):
        return 0.5  # Japanese and Korean "ya" syllables
    if x == "ia":
        return 0.3
    if x.endswith("а") and CYRILLIC_WORD.fullmatch(x):
        return 0.3
    return 0.0


def step(carry, prefix, upstream):
    return carry, float(value_of(prefix.token_strings[-1]))

programs.luna:
"""A small proxy for vowel-final Cyrillic word pieces, often Russian inflections."""
import unicodedata

READS = ()
CYRILLIC_VOWELS = set('аеёиоуыэюяАЕЁИОУЫЭЮЯ')

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].rstrip()
    if token and token[-1] in CYRILLIC_VOWELS:
        if any('CYRILLIC' in unicodedata.name(ch, '') for ch in token):
            return None, 0.3
    return None, 0.0

programs.sol:
"""A sparse lexical approximation of a capacity/containment-related response.

The largest negative predictions are for the CJK character 容 and selected
compounds, including its appearance and tolerance senses. Smaller responses
cover capacity, containers, contents, tolerance, rong homophones, Korean 용,
and Japanese insertion vocabulary. The cross symbol ✝ is a separate trigger.

Spacing, case, a few split compounds, and immediate phrase continuations
adjust the values. Byte fragments are recognized when they finish 容 or 용.
State resets at document boundaries. Unlisted tokens get zero: the many weak,
idiosyncratic token responses are deliberately not represented.
"""

READS = ()

# Compounds keep their familiar senses: storage, appearance, containment,
# tolerance, composure, compatibility, and contents.
CJK_WORDS = {
    '不容': -4.8,
    '容量': -2.55,
    '美容': -2.4,
    '形容': -1.85,
    '容貌': -1.85,
    '容器': -1.75,
    '从容': -1.45,
    '包容': -1.05,
    '宽容': -1.05,
    '容忍': -1.1,
    '容纳': -1.2,
    '面容': -1.1,
    '兼容': -0.52,
    '内容': -0.55,
    '內容': -0.55,
    '的内容': -0.45,
    '不可': -0.58,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    previous = carry[1] if same_doc else ''
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.casefold().lstrip('_(.-/')
    spaced = raw.startswith(' ')
    value = CJK_WORDS.get(token, 0.0)

    if token == '容':
        # Distinguish split compounds from the standalone root.
        before = prefix.text_prefixes[-1][-2:-1] if same_doc else ''
        if before == '内':
            value = -2.0
        elif before in {'电', '電'}:
            value = -3.6
        elif before in {'相', '先', '纵', '縱'}:
            value = -4.1
        else:
            value = -6.3
    elif '\ufffd' in raw and same_doc:
        # Byte-fragment tokens can finish a character without displaying it alone.
        ending = prefix.text_prefixes[-1][-1:]
        if ending == '容':
            value = -6.3
        elif ending == '용':
            value = -2.73
    elif token in {'溶', '融', '荣', '榮', '蓉', '熔'}:
        # Chinese characters with the same spoken syllable, rong.
        value = -1.0
    elif token == '용':
        value = -1.3
    elif token == '내용':
        value = -0.41
    elif token in {'を入れ', '入れ'}:
        value = -0.54 if token == 'を入れ' else -0.18
    elif token == '✝':
        value = -0.81
    elif word == 'capacity':
        value = -1.43 if spaced else -1.1
    elif word == 'capacities':
        value = -1.28
    elif word in {'capac', 'capacit', 'capacidad', 'capacité', 'capacità'}:
        value = -0.67
    elif word == 'acity' and previous == 'cap':
        value = -1.0
    elif word == 'capacitor':
        value = -0.39
    elif word in {'container', 'containers'}:
        value = -0.63
        if spaced:
            value = -0.78 if word == 'container' else -0.91
    elif word == 'contents':
        value = -0.44 if spaced and token.islower() else -0.24
    elif word == 'content':
        value = -0.13 if spaced else -0.08
    elif word == 'conten':
        value = -0.70
    elif word == 'conteúdo':
        value = -0.40
    elif word in {'tolerance', 'tolerant', 'intolerance', 'intoler', 'toler'}:
        value = {'tolerance': -0.64, 'tolerant': -0.84,
                 'intolerance': -1.1, 'intoler': -0.97, 'toler': -0.37}[word]
    elif word in {'tolerate', 'tolerated'}:
        value = -0.16
    elif word == 'unacceptable':
        value = -0.45
    elif word == 'of' and previous in {
        'capacity', 'capacities', 'container', 'containers', 'contents', 'tolerance'
    }:
        value = -0.33 if previous == 'capacity' else -0.28
    elif word == 'for' and previous in {'capacity', 'tolerance'}:
        value = -0.17
    elif word in {'ance', 'ances'} and previous == 'capacit':
        value = -0.20
    elif token == '량' and previous == '용':
        value = -0.4
    return (doc, word), float(value)

programs.luna:
"""Use capacity and containment words as a small lexical cue for negative activation."""

READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().casefold()
    word = word.strip(".,:;!?()[]{}\"'“”‘’")

    # A byte token can be only part of a CJK character; recover its joined spelling.
    if "\ufffd" in raw:
        text = prefix.text_prefixes[-1]
        forms = (
            "不容", "容器", "容量", "內容", "内容", "包容", "容", "용",
        )
        for form in forms:
            if text.endswith(form):
                word = form
                break

    if word.startswith(("capacity", "capacities")):
        value = -1.45
    elif word.startswith("capacit"):
        value = -0.72
    elif word.startswith(("container", "contain", "content")):
        value = -0.60
    elif word in {"不容", "容"}:
        value = -3.0
    elif word in {"容器", "容量", "包容"}:
        value = -1.1
    elif word in {
        "内容", "內容", "용", "融", "不可", "capacité", "conteúdo",
        "tolerance",
    }:
        value = -0.65
    else:
        value = 0.0
    return None, value

programs.sol:
"""Approximate the component's strong response to escaped quotation marks.

Recognize a backslash followed by a double quote within the current token.
Leading whitespace gives the largest pulse, opening syntax a smaller one,
and trailing syntax suppresses it. Escaped apostrophes give a weaker pulse.
Ignore the component's many small responses to ordinary vocabulary.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if '\\"' in token:
        before, after = token.split('\\"', 1)
        if after:
            value = max(0.08, 0.30 - 0.09 * (len(after) - 1))
        elif before.isspace():
            value = 1.08
        elif before.endswith(('(', '[', '{', '=')):
            value = 0.91
        elif '"' in before:
            value = 0.53
        elif before.endswith(('.', '}')):
            value = 0.64
        elif before.endswith('\\'):
            value = 0.15
        else:
            value = 0.80
    elif "\\'" in token:
        value = 0.38 if token.endswith("\\'") else 0.18
    else:
        value = 0.0
    return None, float(value)

programs.luna:
"""Mark formal obligation and case language, where this component is usually negative."""

READS = ()

OBLIGATION_WORDS = {
    "agrees", "hereby", "indemnify", "indemnification", "pursuant",
    "shall", "therein", "deemed", "contemplated", "intended",
    "affiliate", "securities", "disclosure", "consideration",
    "successors", "assigns", "clause", "precedent", "claim",
