"""A spelling cue for conjunction tokens and the recurrent -ung sequence."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    lower = token.lower()

    if "&&" in token:
        return None, -1.15
    if lower.endswith("ung"):
        return None, -2.3
    if "ung" in lower:
        return None, -1.4
    return None, 0.0

programs.sol:
"""A local spelling contrast, plus a few formatting-character responses.

A short word fragment ending in A plus a consonant primes a positive response
to another A-initial fragment, particularly ap/az/av and Cyrillic аз/ав.
I-initial and grammatical endings instead give negative predictions. A space
breaks the link; document starts also boost short A fragments. These rules
capture the conspicuous syllable-boundary responses, not the many smaller
word-specific activations. Latin vowel accents are ignored. Standalone carriage
returns and escaped quotes are negative; repeated hyphens are positive.
"""
import re
import unicodedata

READS = ()
VOWELS = 'aeiouyаеёиоуыэюя'
A_CONSONANT = re.compile('[aа][^' + VOWELS + ']$')
STRONG_A = {'ap', 'az', 'av', 'аз', 'ав'}
I_ENDINGS = {'ic', 'ical', 'ically', 'ity', 'ities', 'ive', 'ives',
             'ious', 'ine', 'iness', 'iveness', 'il', 'ii'}
GRAMMATICAL_ENDINGS = {'ed', 'er', 'ly', 'ing'}


def spelling(raw):
    # Remove Latin diacritics without changing Cyrillic consonants such as й.
    return ''.join(unicodedata.normalize('NFD', c)[0]
                   if 'LATIN' in unicodedata.name(c, '') else c
                   for c in raw.strip().lower())


def fragment_strength(text):
    if (not text.isalpha() or not A_CONSONANT.search(text)
            or any(c in VOWELS and c not in 'aа' for c in text)):
        return 0.0
    return {2: 1.0, 3: 0.65, 4: 0.3, 5: 0.3}.get(len(text), 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    text = spelling(raw)
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    strength = fragment_strength(previous)
    value = -0.0015
    inside_word = bool(raw and raw[0].isalpha())
    if text.startswith(('a', 'а')):
        short = len(text) == 2 and text[1] not in VOWELS
        if start:
            value += (0.33 if inside_word else 0.09) if short else 0.03
            if text in STRONG_A and inside_word:
                value += 0.1
        elif inside_word:
            value += strength * (0.22 if short else 0.14)
            if text in STRONG_A:
                value += strength * 0.13
                if previous.endswith(('al', 'аг', 'ак', 'ал')):
                    value += strength * 0.15
    elif inside_word:
        penalty = (0.26 if text in I_ENDINGS else
                   0.4 if text == 'ness' else
                   0.14 if text in GRAMMATICAL_ENDINGS else
                   0.11 if text[0] in 'iиі' or len(text) == 1 else 0.04)
        value -= strength * penalty
        if text == 'iveness' and previous == 'at':
            value = -0.6
    if raw == '\r':
        value = -0.078
    elif '\\"' in raw and not any(c.isalnum() for c in raw):
        value = -0.033
    elif len(text) >= 2 and set(text) == {'-'}:
        value = 0.044
    return (doc, text), float(value)

"""Lexical signals for major/minor importance, expertise and examples.

Major (in any sense) and Chinese professional-specialty words are strongest.
A few prominence/severity words are weaker; 'for example' and 'for instance'
respond only as phrases. Formatting vocabulary is a separate weak signal.
Case, token boundaries, document position and a few split-word endings affect
the strength. The 'of' following 'majority' has a smaller continuation response.
Unrecognized tokens receive zero rather than their small, irregular activations.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        prev, position = '', 0
    else:
        prev, position = carry[1], carry[2] + 1
    word = token.strip(' \t\r\n_./-(=').lower()
    remembered = word
    value = 0.0

    # Major/minor word family, including selected split-token endings.
    if word == 'major':
        # The main spelling is stronger near the beginning of a document.
        value = 6.0 + 1.4 / (position + 1) ** 0.5
        if token == ' major' and prev == 'a':
            value += 0.6
        elif token == 'Major':
            value = 6.4
        elif token == 'major':
            value = 5.5
        elif token.startswith(('-', '.')):
            value = 4.8
    elif word in ('majors', 'ajor'):
        value = 5.2
    elif word == 'maj':
        value = 1.9
    elif token == 'JOR' and prev == 'ma':
        value = 3.3
    elif token in ('ored', 'ors') and prev == 'maj':
        value = 2.6
    elif token in ('ing', 'ly') and prev == 'major':
        value = 2.7
    elif token == 'ity' and prev == 'major':
        value, remembered = 0.95, 'majority'
    elif word == 'of' and prev == 'majority':
        value = 0.68
    elif word == 'minor':
        value = 3.2 if token == 'Minor' else 2.4
    elif word in ('majority', 'minority', 'minors', 'minorities'):
        value = 1.0
    # Chinese academic-major and professional-specialty words.
    elif token == '专业':
        value = 6.0
    elif token in ('专业的', '的专业', '專業'):
        value = 4.9
    elif token == '专业知识':
        value = 2.8
    # Weaker lexical responses: severity, prominence and expertise.
    elif word == 'serious':
        value = 2.3 + (0.25 if prev == 'a' else 0.0)
    elif word in ('seriously', 'seriousness', 'professional',
                  'professionalism'):
        value = 1.15
    elif word in ('professionals', 'professionally', 'profesional',
                  'amateur', 'leading', 'massive'):
        value = 0.75
    elif word in ('significant', 'potential', 'specialty', 'discipline'):
        value = 0.55
    elif word in ('significantly', 'substantial', 'dominant',
                  'promising', 'profession'):
        value = 0.4
    elif word in ('potent', 'solemn'):
        value = 0.95
    elif token in ('重大', '的重大', ' серь'):
        value = 1.9
    elif token in ('严重', '嚴重', '严重的', '的重要', ' профессиона'):
        value = 1.2
    elif token in ('主要', '的主要'):
        value = 0.75
    # Example-introducing phrases, not the nouns alone.
    elif word in ('example', 'instance') and prev == 'for':
        value = 1.13
    elif word in ('ejemplo', 'exemplo') and prev == 'por':
        value = 1.35
    elif word == 'exemple' and prev == 'par':
        value = 1.0
    elif token == '例如':
        value = 0.5
    # A separate formatting-vocabulary response.
    elif word == 'format':
        value = 0.75
        if token.startswith(('.', '/')):
            value = 1.3
        elif not token.startswith((' ', '\t')):
            value = 0.95
    elif word in ('formats', 'formatting'):
        value = 0.7
    elif token == '格式':
        value = 0.5

    return (doc, remembered, position), float(value)

"""A text-opening signal: quotation marks and square/angle brackets.

East Asian title marks, especially 《, receive the largest values. Other
quotation/bracket marks, bold markers and the literal www prefix are weaker.
Straight quotes are gated by the preceding token's punctuation and word
class to distinguish prose from code/JSON. Braces use familiar TeX command
endings. Most other text gets zero; an unspaced backtick gets a small negative
value. Carry holds only the previous token and its document label.
"""
READS = ()

OPENING_MARKS = {
    '《': 8.1, '〈': 2.6, '『': 2.5, '【': 1.8, '「': 1.3,
    '⟨': 1.4, '＜': 1.05,
}
QUOTE_INTRODUCERS = set('the a an that of to as by for on in at'.split())
CODE_KEYWORDS = set('return case echo print yield throw if then else'.split())
# Endings of TeX commands: e.g. mathbb, mathbf, mathcal.
TEX_COMMAND_ENDINGS = {
    'frac': 0.27, 'sqrt': 0.28, 'ref': 0.27, 'label': 0.05,
    'text': 0.48, 'mathrm': 0.74, 'begin': 0.83, 'end': 0.43,
    'bb': 0.59, 'bf': 0.54, 'cal': 0.64, 'vec': 0.56,
}


def prose_quote(previous, single):
    p = previous.strip()
    if not p:
        return 0.4 if '\n' in previous else 0.0
    if (p in CODE_KEYWORDS or any(c in p for c in '=([{\\+*/|&<>')
            or p.endswith(('":', "':", '",', "',"))):
        return 0.0
    if p == ':':
        return 0.05 if single else 0.3
    if p == ',':
        return 0.07 if single else 0.4
    value = 0.8 if p in QUOTE_INTRODUCERS else 0.6
    if p.endswith(('.', '?', '!')):
        value = 0.55
    return value * (0.65 if single else 1.0)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    p, s = previous.strip(), token.strip()
    spaced = token[:1].isspace()
    value = 0.0
    for mark, magnitude in OPENING_MARKS.items():
        if mark in s and not any(c.isalnum() for c in s):
            value = magnitude
            if mark == '「' and s not in ('「', ' 「'):
                value = 0.9
            break
    else:
        if '\n' in token or '\r' in token:
            value = 0.35 if s == '<' else 0.0
        elif s.endswith(('“', '‘', '«', '„')):
            mark = s[-1]
            value = {'“': 0.76, '‘': 0.65, '«': 1.08, '„': 0.4}[mark]
            if len(s) > 1:
                value = 0.25 if s[0] == '：' else 0.53
            elif not spaced:
                value *= 0.6
                if previous and '\u3400' <= previous[-1] <= '\u9fff':
                    value = 0.88
                elif previous and previous[-1].isalpha():
                    value = -0.05
        elif s.startswith('[') and ']' not in s:
            value = 0.4 if spaced else 0.24
            if len(s) > 1:
                value = 0.6
                if s[1] == "'":
                    value = 0.7
        elif s.startswith(('<', '::<')) and '>' not in s:
            if not s.startswith(('<|', '</', '<!', '<<', '<=')):
                value = 0.4 if spaced else 0.7
                if s.startswith('::<'):
                    value = 0.93
                elif len(s) > 1:
                    value = 1.05 if s[1].isupper() else 0.2
                elif p and p[0].isupper() and len(p) > 1:
                    value = 0.98
                if p.endswith('include'):
                    value = 1.3
                elif p.isdigit() or (len(p) == 1 and p.isalpha()):
                    value = 0.08
