CURLY_QUOTES = frozenset('“‘«„')
ASIAN_OPENERS = frozenset('「『《〈【')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    mark = next((char for char in token if not char.isspace()), '')

    previous = ''
    if len(prefix) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    follows_word = any(char.isalpha() for char in previous)

    if mark == '《':
        return None, 7.5
    if mark in ASIAN_OPENERS:
        return None, 1.4
    if mark in CURLY_QUOTES:
        return None, 0.75 if follows_word else 0.45
    if mark == '[':
        return None, 0.42 if follows_word else 0.25
    if mark == '{':
        return None, 0.14 if follows_word else 0.0
    if mark == '<':
        return None, 0.22 if follows_word else 0.03
    if mark == '"':
        return None, 0.12 if follows_word else 0.04
    return None, 0.0

