def fading(position, floor, height, offset, power=1.0):
    """A boundary response approaching its floor as the document gets longer."""
    return floor + height / (position + offset) ** power


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
