        pos, previous, role = carry[1:]
    if previous == '<|im_start|>':
        role = token

    value = 0.060 * exp(-pos / 2.5) - 0.006 * exp(-pos / 150) - 0.0005
    if token == '<|im_start|>':
        value = 1.469 if pos == 0 else fading(pos, -0.021, 1.52, 5, 0.75)
    elif previous == '<|im_start|>':
        if token == 'user':
            value = 0.712 if pos == 1 else fading(pos, -0.036, 75.6, 12, 2)
        elif token == 'assistant':
            value = 0.776 if pos == 1 else fading(pos, 0.0125, -0.141, 4, 0.65)
        elif token == 'system':
            value = 0.975 if pos == 1 else 0.020
    elif token == '<|im_end|>':
        if pos == 0:
            value = 0.864
        elif previous in ('</tool_call>', '</tool_response>'):
            value = fading(pos, 0.109, 5.13, 4)
        elif role == 'assistant':
            value = fading(pos, -0.148, 13.9, 32, 1.25)
        elif role == 'user':
            value = fading(pos, -0.091, 242, 24, 2)
        else:
            value = fading(pos, -0.137, 9.47, 10, 1.25)
    elif token == 'package':
        value = 1.159 if pos == 0 else fading(pos, 0.055, 2.38, 32, 0.5)
    elif token == ' package':
        value = 0.098
    elif token == 'namespace' and pos <= 4:
        value = 0.40
    elif token in ('import', 'using') and pos == 0:
        value = 0.187
    elif token == '<tool_call>':
        value = 1.106 if pos == 0 else fading(pos, 0.031, 0.382, 1, 0.65)
    elif token == '</tool_call>':
        value = 0.967 if pos == 0 else fading(pos, -0.094, 1.18, 1, 0.75)
    elif token == '<tool_response>':
        value = fading(pos, -0.080, 0.711, 2, 0.5)
    elif token == '</tool_response>':
        value = min(0.9, fading(pos, -0.156, 6.37, 1, 1.25))
    elif token == '<think>':
        value = fading(pos, -0.014, 0.658, 1, 0.5)
    elif token == '</think>':
        value = fading(pos, -0.142, 0.499, 10, 0.5)
    return (doc, pos + 1, token, role), float(value)

