"""Spelling continuations after t, with signed weights for the opening letters.

Vowels followed by r/n/l generally excite; selected o/e openings inhibit.
The cross-boundary tch spelling excites; ing/ion openings reduce the score.
Long fragments weaken the response. Cyrillic letters use approximate Latin
spellings; Greek tau and Arabic te have small parallel letter-class rules.
Spaces, punctuation, and unrelated boundaries normally give zero.
"""
import math
import unicodedata

READS = ()
VOWEL_WEIGHT = dict(a=0.46, e=0.08, i=0.17, o=-0.27, u=-0.09)
# Adjustments for a vowel followed by one of the listed letters.
ONSET_ADJUSTMENTS = (
    ('a', 'hw', 0.39),
    ('a', 'tsp', -0.26),
    ('e', 'stkgphz', -0.46),
    ('i', 'gv', 0.16),
    ('o', 'bdtmgz', -0.46),
    ('u', 'tie', -0.33),
)
CYRILLIC = str.maketrans(
    dict(zip('абвгдежзийклмнопрстуфхцыэюя',
             'abvgdejziiklmnoprstufhcyeua'))
    | {'я': 'ya', 'ю': 'yu'}
)


def letters(text):
    text = unicodedata.normalize('NFD', text.lower().translate(CYRILLIC))
    return ''.join(c for c in text if not unicodedata.combining(c))


def spelling_score(s):
    first = s[0]
    score = 0.03 + VOWEL_WEIGHT.get(first, 0.0)
    if first in 'rl':
        score += 0.87
    elif first in 'nw':
        score += 0.56
    if len(s) == 1:
        return score + 0.12
    second = s[1]
    if second in 'rnl':
        score += 0.56
    elif second in 'aeiou':
        score -= 0.10
    if first in 'ai' and second in 'nr':
        score += 0.20
    for vowel, following, adjustment in ONSET_ADJUSTMENTS:
        if first == vowel and second in following:
            score += adjustment
    if s.startswith('ch'):
        score += 0.51
    if len(s) > 2:
        if s[2] in 'nr':
            score += 0.30
        elif s[2] == 't':
            score -= 0.17
    if s.endswith('t'):
        score -= 0.27
    if s.startswith(('ing', 'ion')):
        score -= 0.60
    if s.endswith('s'):
        score -= 0.04
    return score


# Letter classes, not token identities: liquids, nasals and vowel letters.
ARABIC_ONSETS = (('رل', 1.25), ('ن', 0.90), ('اي', 0.55),
                 ('و', -0.10), ('ّ', 1.0))
GREEK_LETTERS = (('εέιίὶρ', 0.55), ('αὰ', 0.35),
                 ('ά', 0.70), ('οηωυ', -0.25))


def letter_weight(groups, char, default):
    for characters, value in groups:
        if len(char) == 1 and char in characters:
            return value
    return default


def continuation(previous, token):
    previous = previous.lower()
    if previous.endswith('ت'):
        if not (token.isalpha() or token == 'ّ'):
            return 0.0
        value = letter_weight(ARABIC_ONSETS, token[:1], 0.0)
    elif previous.endswith('τ') and token.isalpha():
        value = (-0.62 if token == 'ου' else
                 letter_weight(GREEK_LETTERS, token, 0.12))
    elif token.isalpha():
        if previous.endswith(('t', 'т')):
            strength = 1.0
        elif previous.endswith(('th', 'te')):
            strength = 0.35
        else:
            return 0.0
        token = letters(token)
        value = strength * spelling_score(token)
    else:
        return 0.0
    decay = 0.3 * (max(0, len(previous.strip()) - 3)
                   + max(0, len(token) - 3))
    return value * math.exp(-decay)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, token), float(continuation(previous, token))

