        return None, 0.0
    word = prefix.token_strings[-1]
    body = word.lstrip(" ")
    if not body:
        return None, -0.35                      # space or newline after the article
    if not body[0].isalnum():
        return None, (-0.3 if word.startswith(" ") else -0.6)  # symbol or punctuation
    if not word.startswith(" "):
        return None, -0.85                      # word fragment: "a" is part of a longer word
    if body in FUNCTION_WORDS:
        return None, -0.85
    if len(body) == 1:
        return None, -0.2                       # a single letter, e.g. a variable
    if body[0].isupper():
        return None, 0.45
    if len(body) == 2:
        return None, 0.1
    return None, 1.0                            # a content word: noun or adjective

