"""Negative activation for examples and test-case or input/output labels.

Headings and numbered instances strengthen the signal. A literal sample input
or sample output is especially strong. The recent twelve tokens provide only
these simple phrase/formatting cues, reset at document boundaries. A small
multilingual example-word set is included. Other text is treated as inactive;
this does not attempt to reproduce the component's weak background responses.
"""
READS = ()
EXAMPLES = {'example', 'examples', 'sample', 'samples'}
IO = {'input', 'inputs', 'output', 'outputs'}
TESTS = {'test', 'tests'}
BASE = {
    'example': -0.72, 'examples': -0.49, 'sample': -0.39, 'samples': -0.08,
    'input': -0.33, 'inputs': -0.25, 'output': -0.45, 'outputs': -0.31,
    'test': -0.15, 'tests': -0.19, 'case': -0.12, 'cases': -0.25,
    'instance': -0.05, 'explanation': -0.10,
}
TRANSLATIONS = {
    '例如', '例', '示例', '样例', '案例', '比如', 'مثال',
    'пример', 'например', 'имер', 'апример',  # Russian words and their endings.
    'ejemplo', 'exemple', 'exemplo',
    '例えば', '예', '예제', 'dụ', '输入', '输出', '입력', '출력',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry and carry[0] == doc else ()
    token = prefix.token_strings[-1]
    s = token.strip()
    word = s.lower()
    previous = recent[-1] if recent else ''
    prev = previous.strip().lower()
    title = s.istitle()
    line = ''.join(recent).replace('\\n', '\n').rsplit('\n', 1)[-1]
    heading = not line.strip(' \t\r#/*`') or '#' in previous
    ordinal = prev in {'first', 'second', 'third', 'fourth', 'last'}
    near = any(x.strip().lower() in EXAMPLES for x in recent)
    value = BASE.get(word, -0.65 if word in TRANSLATIONS else 0.0)
    if word in EXAMPLES:
        value -= 0.2 * title + 0.55 * heading
        value -= (0.8 if word == 'sample' else 0.6) * ordinal
        value -= 0.8 * ('`' in previous) + 0.7 * (not recent)
        if (word == 'example' and previous.strip() == 'For') or (
                word == 'sample' and prev == 'the'):
            value -= 0.25
    elif word in IO:
        value -= 0.35 * title + (0.75 if title else 0.3) * heading
        if near:
            value -= (2.5 if word == 'input' else 0.9) if title else 0.65
        if prev == 'sample' and word in {'input', 'output'}:
            value = -3.4 if word == 'input' else -2.85
            if title and previous.strip().istitle():
                value = -5.6 if word == 'input' else -4.7
    elif word in TESTS:
        value -= 0.25 * title + 0.30 * heading + 0.5 * ordinal
        value += 0.18 * (not token[:1].isspace())
    elif word in {'case', 'cases'}:
        value -= 0.17 * title + 0.25 * ordinal + 0.85 * (prev in TESTS)
    elif word == 'instance' and prev == 'for':
        value -= 0.49
    elif word == 'explanation' and title and heading:
        value = -0.9
    if (word in TESTS | IO and not token[:1].isspace()
            and previous[-1:].isalnum()):
        value = 0.0  # An identifier suffix, not a standalone label.
    if s.startswith(('.', '/', '_', '(')):
        if s.lstrip('./_(').lower() in EXAMPLES | IO | TESTS | {'log'}:
            value = -0.20
    # The abbreviation e.g., not a filename ending in .g.
    if s == '.g' and prev.lstrip('([') == 'e':
        value = -0.47
    elif s == '>>>':
        value = -0.70  # Interactive Python example prompt.
    elif s == 'RUN':
        value = -0.41  # Test-execution label.
    return (doc, (recent + (token,))[-12:]), float(value)

