    "anybody", "elsewhere", "autres", "otros", "otro", "otra", "andere", "anderen",
    "altro", "altri", "outros", "其他", "有人", "大家",
}
SOME_WORDS = {"some", "<|endoftext|>"}
QUANTIFIERS = {
    "all", "those", "many", "few", "several", "ones", "individuals", "adults",
    "todos", "tous", "tutti", "alle", "plusieurs", "многие", "многих",
}
