programs.sol:
"""Detect a noun-phrase start after a clause cue.

The strongest pattern is 'if/when/that ... the'; possessives, demonstratives,
and quantifiers respond less. Similar Romance-language patterns are included.
Pronoun subjects and -ing continuations have small signed responses instead.
Capitalized question auxiliaries and document-initial clause words have
separate responses. The trailing word is reconstructed across tokens and
resets per document.
This approximates the strong grammatical response, not weak lexical background.
"""
import re

READS = ()
CUES = {
    'when': 5.0, 'if': 4.8, 'whether': 4.7, 'whenever': 4.5,
    'where': 4.2, 'how': 4.1, 'unless': 4.0, 'once': 4.0,
    'which': 3.6, 'why': 3.6, 'what': 3.5, 'that': 3.4,
    'until': 3.2, 'whereby': 3.2, 'wherein': 3.0,
    'because': 2.6, 'while': 2.4, 'since': 2.4, 'whom': 2.4,
    'although': 2.3, 'though': 2.2, 'before': 2.1, 'after': 2.1,
    'maybe': 2.1, 'perhaps': 1.9, 'however': 1.7,
    'so': 1.3, 'then': 1.2, 'but': 1.1, 'as': 1.0,
    'between': 0.85, 'than': 0.7,
    'sure': 3.4, 'way': 2.8, 'time': 2.4,
    # Romance conjunctions and relative words.
    'que': 3.4, 'che': 2.4, 'si': 4.8, 'se': 3.2,
    'cuando': 3.8, 'quando': 3.8, 'donde': 3.6, 'où': 3.0,
    'lorsque': 3.7, 'como': 1.1, 'porque': 2.6,
}
VERBS = {
    'suppose': 2.7, 'ensure': 2.5, 'think': 2.2,
    'hope': 1.9, 'imagine': 1.9, 'assume': 1.8, 'expect': 1.8,
    'let': 1.8, 'say': 1.7, 'believe': 1.7, 'allow': 1.1,
    'know': 1.0, 'want': 0.9, 'make': 0.85, 'need': 0.8,
}
# Each group has a response gain and offset, not token IDs.
GROUPS = (
    ('the', 1.0, 0.0),
    ('a an', 0.78, -0.5),
    ('this these those', 0.62, 0.05),
    ('my your his her its our their all some', 0.7, 0.0),
    ('any no each every both most such certain another several '
     'one two three four five six seven eight nine ten', 0.53, -0.15),
    ('someone somebody something everyone everybody everything', 0.65, -0.1),
    ('anyone anybody anything nothing nobody', 0.5, -0.3),
    ('there that', 0.28, -0.1),
    ('much many only new other different more', 0.25, -0.1),
    ('what which when if', 0.2, -0.2),
    ('la el', 0.45, 0.0),
    ('le les los las o os un una su il mi nuestra nuestro '
     'nuestras nuestros mis tu tus sus', 0.32, 0.0),
)
STARTERS = {w: (g, b) for words, g, b in GROUPS for w in words.split()}
PERSONAL = set('I you he she we they'.split())
PRONOUN_RESPONSE = {
    'when': -0.9, 'where': -0.9, 'how': -0.9, 'what': -0.55,
    'if': -0.3, 'that': -0.15, 'because': -0.15,
    'since': -0.15, 'while': -0.15, 'as': 0.25,
}
INITIAL = {
    'that': 1.55, 'what': 1.9, 'which': 1.0, 'where': 1.0,
    'how': 0.95, 'whether': 1.0, 'if': 0.75,
}


def cue_strength(word):
    word = {'thought': 'think', 'said': 'say', 'knew': 'know',
            'made': 'make'}.get(word, word)
    if word in CUES or word in VERBS:
        return CUES.get(word, VERBS.get(word, 0.0))
    for ending in ('s', 'ing', 'ed', 'd'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            if stem in VERBS or stem + 'e' in VERBS:
                return VERBS.get(stem, VERBS.get(stem + 'e', 0.0))
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    initial = carry is None or carry[0] != doc
    tail = '' if initial else carry[1]
    match = re.search(r'([^\W\d_]+)$', tail)
    previous = match.group().lower() if match else ''
    capital = bool(match) and match.group()[0].isupper()
    strength = cue_strength(previous)
    if capital and previous in ('if', 'as'):
        strength += 0.4
    if capital and previous in ('does', 'is', 'can', 'will', 'should'):
        strength = 1.5
    value = 0.0
    if strength and token.startswith(' ') and token[1:].isalpha():
        word = token[1:]
        if word.lower() in STARTERS:
            gain, offset = STARTERS[word.lower()]
            value = max(0.0, gain * strength + offset)
            if word[0].isupper():
                value *= 0.5
        elif word in PERSONAL:
            value = PRONOUN_RESPONSE.get(previous, 0.0)
            if previous == 'if' and capital:
                value = 0.05
        elif word.endswith('ing') and len(word) >= 5:
            value = 0.5 - 0.45 * strength
        if previous == 'as' and word in ('a', 'an'):
            value = 0.0
    elif strength and token == ' ':
        value = 0.22 * strength
    if initial:
        word = token.strip()
        if word.lower() in INITIAL:
            value = INITIAL[word.lower()]
            if word[0].isupper() or not token.startswith(' '):
                value *= 0.4
        elif word.lower() in ('my', 'her', 'your', 'our', 'his', 'their'):
            value = -0.3
        elif token == ' the':
            value = 0.2
        elif word == 'The':
            value = -0.2
    tail = (tail + token).replace('\\n', '\n')[-40:]
    return (doc, tail), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:2361 as a readable rule.

What it does: it fires on a determiner or quantifier word ("the", "a", "this",
"their", "my", "your", "all", "everything", ...) when that word opens a noun phrase
that sits right after a clause-introducing word. The larger the activation, the
stronger the clause word:

  - "if", "when", "whether", "where", "how", "which", "what", "who", "why", "once",
    "although", "though"                                   -> about 3.5  ("when the user")
  - "that"                                                  -> about 2.5  ("that the")
  - "because", "since", "while", "until", "after", "before" -> about 2.0
  - "so", "but", "as", "then", "maybe", "perhaps", "think", "said", "says",
    "let", "make", "than", "like"                           -> about 1.0
  - anything else (prepositions "in the", "of the", punctuation, ...) -> 0
  - prepositions ("in the", "on the", "of the", "from the") and punctuation -> 0

Each word is looked at only with the one word before it, inside the same document.
Tokens are compared after stripping spaces and lower-casing.
"""

DETERMINERS = {
    "the", "a", "an", "this", "that", "these", "those", "his", "her", "their",
    "my", "your", "our", "its", "all", "any", "some", "every", "each",
    "everything", "everyone", "someone", "anyone", "none", "neither", "one",
    "whose", "no", "both", "such",
}
WH_WORDS = {
    "if", "when", "whether", "where", "how", "which", "what", "who", "whom",
    "why", "once", "although", "though", "wherein",
}
CLAUSE_CONJUNCTIONS = {"because", "since", "while", "until", "till", "after", "before"}
WEAK_CLAUSE_WORDS = {
    "so", "but", "as", "then", "maybe", "perhaps", "think", "said", "says",
    "let", "make", "making", "made", "than", "like",
}

READS = ()


def strength(previous):
    """How strongly a determiner after this word fires."""
    if previous in WH_WORDS:
        return 3.5
    if previous == "that":
        return 2.5
    if previous in CLAUSE_CONJUNCTIONS:
        return 2.0
    if previous in WEAK_CLAUSE_WORDS:
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    t = prefix.position
    word = tokens[t].strip().lower()
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, 0.0
    if word not in DETERMINERS:
        return None, 0.0
    previous = tokens[t - 1].strip().lower()
    return None, float(strength(previous))

programs.luna:
"""A small text heuristic for sparse article-like responses. It gives
articles a baseline, raises them after common clause and discourse linkers,
and lowers some pronouns and -ing words after temporal linkers."""
READS = ()

ARTICLES = {"the": 0.32, "a": 0.07, "an": 0.12}
STRONG_LINKERS = {"if", "when", "whether", "where"}
CLAUSE_LINKERS = {
    "which", "what", "that", "until", "while", "since", "after", "before",
}
OTHER_LINKERS = {
    "perhaps", "maybe", "so", "then", "but", "as", "because",
    "although", "though", "once", "unless",
}

PRONOUNS = {"i", "we", "you", "he", "she", "they", "it"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = ARTICLES.get(word, 0.0)
    if len(prefix.token_ids) < 2:
        return None, value
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, value
    previous = prefix.token_strings[-2].strip().lower()
    if word == "the":
        if previous in STRONG_LINKERS:
            value = 4.8
        elif previous in CLAUSE_LINKERS:
            value = 3.1
        elif previous in OTHER_LINKERS:
            value = 1.7
    elif word == "a" and previous in {"when", "if"}:
        value = 3.2
    elif word == "a" and previous == "that":
        value = 2.0
    elif word == "this" and previous == "that":
        value = 2.2
    # After temporal or interrogative linkers, pronouns and -ing forms
    # tend to produce a smaller negative response instead of an article burst.
    if previous == "when" and (
        word in PRONOUNS or (word.isalpha() and word.endswith("ing"))
    ):
        value = -0.9
    elif previous in {"where", "how"} and word in PRONOUNS:
        value = -0.7
    elif previous == "while" and word.isalpha() and word.endswith("ing"):
        value = -0.6
    return None, value

"""Mark words about harm and protection, plus selected complements of 'for'."""
