            if first not in VOWELS and second and second in LATIN:
                value += 0.11 if second == 'e' else 0.02
            if token.startswith('ch'):
                value += 0.10
        if last and first in GREEK and last in GREEK:
            value += 0.33
        if last and first in ARABIC and last in ARABIC:
            value += 0.20
    if raw and raw[0] in 'ิีึืุู' and previous_raw:
        if '\u0e01' <= previous_raw[-1] <= '\u0e2e':
            value += 0.04
            if 'เ' in previous_raw:
                value += 0.38
    return (doc, raw, token), float(value)

"""A sparse lexical response to streets and nearby public-space vocabulary.

'Street' and 街 have the largest negative responses. Other road names,
translations, neighborhood/social words, and spelling fragments are weaker.
Main Street is stronger than Wall Street. A fragment completing 'street'
is stronger than the same fragment elsewhere. Unmatched tokens give zero.
"""

READS = ()

STREET_SYNONYMS = {
    'avenue', 'boulevard', 'blvd', 'broadway', 'sidewalk',
    'straße', 'straßen', 'calle', 'rua',
}
LOCAL_PUBLIC_SPACE = {
    'town', 'urban', 'district', 'traffic', 'church', 'saint',
    'hall', 'shopping', 'retail', 'neighborhood', 'neighborhoods',
    'neighbourhood', 'neighbourhoods', '社会', '道', '店',
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lstrip('._-').lower()
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip()

    if word == 'street':
        value = -7.0
        if previous == 'Main':
            value = -8.35
        elif previous == 'Wall':
            value = -5.65
        elif raw == ' street':
            value = -7.3
    elif word == 'streets':
        value = -5.1
    elif word in STREET_SYNONYMS:
        value = -2.4
    elif word in {'road', 'roads', 'freeway', 'rue'}:
        value = -1.9
        if raw == ' Road':
            value = -2.2
        elif raw == 'road':
            value = -1.0
    elif word in {'highway', 'highways', 'hwy', 'avenues', 'sidewalks'}:
        value = -1.6
    elif word in {'driveway', 'pavement', 'alley', 'roadside', 'roadway',
                  'downtown', 'phố', '海滩', '广场', '社交'}:
        value = -1.3
    elif word in {'beach', 'beaches'}:
        value = -1.0 if token[:1].isupper() else -1.45
    elif word in {'lane', 'backyard', 'artery', '国道'}:
        value = -0.7
    elif word == 'lanes':
        value = -0.3
    elif token == '街':
        value = -8.6
    elif token in {'街上', '大街'}:
        value = -6.0
    elif token in {'街道', '街头'}:
        value = -4.8
    elif '街' in token or token in {'巷', '马路', '路边'}:
        value = -2.6
    elif token in {'町', '沙滩'}:
        value = -2.1
    elif token in {'路', '道路', '大道', '路上', '公路'}:
        value = -1.0
    elif token == 'St':
        value = -1.0 if raw.startswith(' ') else -0.6
    elif token in {'st', '-st', 'ST'}:
        value = -0.25
    elif word == 'reet':
        value = -2.8
        if previous.lower().endswith('st'):
            value = -6.3 if previous == '-st' else -5.2
    elif word == 'levard':
        value = -2.2
    elif word in {'ave', 'stra'}:
        value = -0.8
    elif word in {'social', 'socially', 'sociale', 'sociales'}:
        value = -0.5 if token[:1].isupper() else -0.75
    elif word in LOCAL_PUBLIC_SPACE:
        value = -0.4
    else:
        value = 0.0

    # A byte fragment can finish a street/shop character in the decoded text.
    if '\ufffd' in token:
        completed = prefix.text_prefixes[-1][-1:]
        if completed == '街':
            value = -7.7
        elif completed == '店':
            value = -2.0
    return None, value
